from math import fsum, sqrt
from numbers import Number

def most_correlated_columns(data):
    names = list(data)
    if len(names) < 2 or not data[names[0]]:
        raise ValueError("At least two non-empty columns are required")

    length = len(data[names[0]])
    centered = {}
    variance = {}

    for name in names:
        values = data[name]
        if len(values) != length:
            raise ValueError("Columns must have equal lengths")
        if any(not isinstance(x, Number) or isinstance(x, complex) for x in values):
            raise TypeError("Columns must contain real numbers")

        values = [float(x) for x in values]
        mean = fsum(values) / length
        centered[name] = [x - mean for x in values]
        variance[name] = fsum(x * x for x in centered[name])

    best_pair = None
    best_correlation = -1.0

    for i, first in enumerate(names):
        for second in names[i + 1:]:
            if variance[first] == 0 or variance[second] == 0:
                continue  # Pearson correlation is undefined for constant columns.

            numerator = fsum(
                x * y for x, y in zip(centered[first], centered[second])
            )
            correlation = abs(numerator / (
                sqrt(variance[first]) * sqrt(variance[second])
            ))
            if correlation > best_correlation:
                best_correlation = correlation
                best_pair = (first, second)

    if best_pair is None:
        raise ValueError("No pair has a defined Pearson correlation")
    return best_pair
