        squared_sums[name] = fsum(x * x for x in centered[name])
        if squared_sums[name] == 0:
            raise ValueError("Pearson correlation is undefined for constant columns")

    best_pair = None
    best_correlation = -1

    for first, second in combinations(names, 2):
        numerator = fsum(
            x * y for x, y in zip(centered[first], centered[second])
        )
        correlation = abs(numerator) / (
            sqrt(squared_sums[first]) * sqrt(squared_sums[second])
        )
        if correlation > best_correlation:
            best_correlation = correlation
            best_pair = (first, second)

