import cmath
import math


def discrete_fourier_transform(signal, precision=2):
    """Return the unnormalised forward DFT as (real, imaginary) tuples."""
    n = len(signal)

    def rounded(value):
        result = round(value, precision)
        return 0.0 if result == 0 else result

    return [
        (
            rounded(value.real),
            rounded(value.imag),
        )
        for k in range(n)
        for value in [
            sum(
                sample * cmath.exp(-2j * math.pi * k * t / n)
                for t, sample in enumerate(signal)
            )
        ]
    ]
