def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must not be empty")
    if n_clusters <= 0 or n_clusters > len(points):
        raise ValueError("n_clusters must be between 1 and len(points)")

    data = sorted((float(x), float(y)) for x, y in points)

    def distance_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Choose deterministic, well-spaced starting centers.
    centers = [data[0]]
    while len(centers) < n_clusters:
        centers.append(
            max(data, key=lambda p: min(distance_sq(p, c) for c in centers))
        )

    for _ in range(300):
        groups = [[] for _ in range(n_clusters)]
        for i, point in enumerate(data):
            closest = min(range(n_clusters), key=lambda j: distance_sq(point, centers[j]))
            groups[closest].append(i)

        # Give empty clusters a point from a cluster that has more than one.
        for group in groups:
            if group:
                continue
            donor = max(
                (g for g in groups if len(g) > 1),
                key=lambda g: max(
                    distance_sq(data[i], centers[groups.index(g)]) for i in g
                ),
            )
            farthest = max(donor, key=lambda i: distance_sq(data[i], centers[groups.index(donor)]))
            donor.remove(farthest)
            group.append(farthest)

        updated = [
            (
                sum(data[i][0] for i in group) / len(group),
                sum(data[i][1] for i in group) / len(group),
            )
            for group in groups
        ]
        if updated == centers:
            break
        centers = updated

    return [list(center) for center in sorted(centers)]
