import math
import re
from collections import Counter


def text_similarity_scores(text1, text2):
    def clean(text):
        return re.sub(r"[\W_]+", " ", text.lower())

    a, b = clean(text1), clean(text2)
    counts_a, counts_b = Counter(a.split()), Counter(b.split())

    if not counts_a or not counts_b:
        cosine = 0.0
    else:
        dot = sum(count * counts_b[word] for word, count in counts_a.items())
        norm_a = math.sqrt(sum(count * count for count in counts_a.values()))
        norm_b = math.sqrt(sum(count * count for count in counts_b.values()))
        cosine = dot / (norm_a * norm_b)

    # The minimum number of insertions and deletions is determined by
    # the length of the longest common subsequence (LCS).
    if len(b) > len(a):
        a, b = b, a
    previous = [0] * (len(b) + 1)
    for char_a in a:
        current = [0] * (len(b) + 1)
        for j, char_b in enumerate(b, 1):
            current[j] = (
                previous[j - 1] + 1
                if char_a == char_b
                else max(previous[j], current[j - 1])
            )
        previous = current

    ratio = 2 * previous[-1] / (len(a) + len(b)) if a or b else 1.0
    return cosine, ratio
