import math
import re
from collections import Counter


def text_similarity_scores(text1, text2):
    def clean(text):
        return re.sub(r"[\W_]+", " ", text.lower())

    a, b = clean(text1), clean(text2)
    counts_a, counts_b = Counter(a.split()), Counter(b.split())

    if counts_a and counts_b:
        dot = sum(count * counts_b[word] for word, count in counts_a.items())
        magnitude_a = math.sqrt(sum(count ** 2 for count in counts_a.values()))
        magnitude_b = math.sqrt(sum(count ** 2 for count in counts_b.values()))
        cosine = dot / (magnitude_a * magnitude_b)
    else:
        cosine = 0.0

    if a == b:
        ratio = 1.0
    else:
        # Find the longest common subsequence using O(min(len(a), len(b))) space.
        if len(b) > len(a):
            a, b = b, a
        dp = [0] * (len(b) + 1)
        for char_a in a:
            diagonal = 0
            for j, char_b in enumerate(b, 1):
                previous = dp[j]
                dp[j] = (diagonal + 1 if char_a == char_b
                         else max(dp[j], dp[j - 1]))
                diagonal = previous
        ratio = 2 * dp[-1] / (len(a) + len(b))

    return cosine, ratio
```

The ratio uses the longest common subsequence, so it reflects the minimum number of insertions and deletions.

