from math import fsum, sqrt

def standardize_age_score(records):
    unique = {}
    for name, age, score in records:
        if name not in unique:
            unique[name] = (age, score)

    if not unique:
        return []

    ages, scores = zip(*unique.values())

    def z_scores(values):
        mean = fsum(values) / len(values)
        std = sqrt(fsum((value - mean) ** 2 for value in values) / len(values))
        return [0.0 if std == 0 else (value - mean) / std for value in values]

    return [
        (name, age_z, score_z)
        for name, age_z, score_z in zip(
            unique, z_scores(ages), z_scores(scores)
        )
    ]
