def standardize_age_score(records):
    unique = {}
    for name, age, score in records:
        if name not in unique:
            unique[name] = (age, score)

    if not unique:
        return []

    values = list(unique.values())
    n = len(values)

    age_mean = fsum(age for age, _ in values) / n
    score_mean = fsum(score for _, score in values) / n

    age_sd = sqrt(fsum((age - age_mean) ** 2 for age, _ in values) / n)
    score_sd = sqrt(fsum((score - score_mean) ** 2 for _, score in values) / n)

    return [
        (
            name,
            (age - age_mean) / age_sd if age_sd else 0.0,
            (score - score_mean) / score_sd if score_sd else 0.0,
        )
        for name, (age, score) in unique.items()
    ]
