import math

def column_correlation_matrix(data, cols):
    width = len(cols)
    if any(len(row) != width for row in data):
        raise ValueError("Each row must have one value per column")

    if not data:
        return [[math.nan for _ in cols] for _ in cols]

    columns = list(zip(*data))
    means = [math.fsum(column) / len(data) for column in columns]
    centered = [
        [value - mean for value in column]
        for column, mean in zip(columns, means)
    ]
    sums_of_squares = [math.fsum(x * x for x in column) for column in centered]

    result = [[math.nan] * width for _ in cols]
    for i in range(width):
        for j in range(i, width):
            if sums_of_squares[i] > 0 and sums_of_squares[j] > 0:
                if i == j:
                    correlation = 1.0
                else:
                    numerator = math.fsum(
                        x * y for x, y in zip(centered[i], centered[j])
                    )
                    correlation = numerator / math.sqrt(
                        sums_of_squares[i] * sums_of_squares[j]
                    )
                result[i][j] = result[j][i] = correlation

    return result
```

Correlations involving a constant column, or with no rows, are undefined and returned as `math.nan`.

