def letter_count_correlations(strings):
    if not strings:
        return None

    counts = [Counter(string) for string in strings]
    letters = sorted(set().union(*(count.keys() for count in counts)))

    centered = {}
    norms = {}
    for letter in letters:
        values = [count[letter] for count in counts]
        mean = fsum(values) / len(values)
        centered[letter] = [value - mean for value in values]
        norms[letter] = sqrt(fsum(value * value for value in centered[letter]))

    result = {letter: {} for letter in letters}
    for i, x in enumerate(letters):
        for y in letters[i:]:
            correlation = (
                1.0 if x == y else
                fsum(a * b for a, b in zip(centered[x], centered[y]))
                / (norms[x] * norms[y])
            )
            result[x][y] = result[y][x] = correlation

