    counts = [Counter(s) for s in strings]
    letters = sorted(set().union(*(count.keys() for count in counts)))

    centered = {}
    sum_squares = {}
    for letter in letters:
        values = [count[letter] for count in counts]
        mean = fsum(values) / len(strings)
        centered[letter] = [value - mean for value in values]
        sum_squares[letter] = fsum(v * v for v in centered[letter])

    result = {letter: {letter: 1.0} for letter in letters}
    for x, y in combinations(letters, 2):
        covariance = fsum(a * b for a, b in zip(centered[x], centered[y]))
        correlation = covariance / sqrt(sum_squares[x] * sum_squares[y])
        result[x][y] = result[y][x] = correlation

    return result
