def letter_count_correlations(strings):
    if not strings:
        return None

    counts = [Counter(s) for s in strings]
    letters = sorted(set().union(*(count.keys() for count in counts)))

    vectors = {
        letter: [count[letter] for count in counts]
        for letter in letters
    }
    centered = {
        letter: [value - sum(values) / len(values) for value in values]
        for letter, values in vectors.items()
    }
    lengths = {
        letter: sqrt(sum(value * value for value in values))
        for letter, values in centered.items()
    }

    result = {letter: {} for letter in letters}
    for i, x in enumerate(letters):
        result[x][x] = 1.0
        for y in letters[i + 1:]:
            correlation = sum(
                a * b for a, b in zip(centered[x], centered[y])
            ) / (lengths[x] * lengths[y])
            result[x][y] = correlation
            result[y][x] = correlation

    return result
