import csv
import io
import math


def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    headers = next(reader, [])
    columns = {header: [] for header in headers}

    if len(columns) != len(headers):
        raise ValueError("Column names must be unique")

    for row in reader:
        if len(row) != len(headers):
            raise ValueError("Each row must have the same number of fields as the header")
        for header, value in zip(headers, row):
            columns[header].append(value)

    numeric_count = 0

    for header, values in columns.items():
        try:
            numbers = [float(value) for value in values]
        except ValueError:
            continue

        if not numbers or not all(math.isfinite(number) for number in numbers):
            continue

        numeric_count += 1
        low, high = min(numbers), max(numbers)
        columns[header] = (
            [0.0] * len(numbers)
            if low == high
            else [(number - low) / (high - low) for number in numbers]
        )

    if numeric_count == 0:
        raise ValueError("The data has no numeric columns")

    return columns
```

