import csv
import io
import re
from collections import Counter

def top_word_counts(csv_text):
    stop_words = {"a", "an", "the", "in", "on", "at", "and", "or"}
    counts = Counter()

    for row in csv.reader(io.StringIO(csv_text, newline="")):
        if row:
            counts.update(
                word
                for match in re.finditer(r"\w{2,}", row[0])
                if (word := match.group().casefold()) not in stop_words
            )

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:10]
