```python
from html.parser import HTMLParser


def first_tag_text(html, tag):
    tag = tag.lower()
    void_tags = {
        "area", "base", "br", "col", "embed", "hr", "img", "input",
        "link", "meta", "param", "source", "track", "wbr",
    }

    class FirstTagParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.found = False
            self.done = False
            self.depth = 0
            self.parts = []

        def handle_starttag(self, name, attrs):
            if self.done or name != tag:
                return
            if not self.found:
                self.found = True
            if name in void_tags:
                self.done = True
            else:
                self.depth += 1

        def handle_startendtag(self, name, attrs):
            if not self.found and name == tag:
                self.found = True
                self.done = True

        def handle_endtag(self, name):
            if self.depth and name == tag:
                self.depth -= 1
                if self.depth == 0:
                    self.done = True

        def handle_data(self, data):
            if self.depth and not self.done:
                self.parts.append(data)

    parser = FirstTagParser()
    parser.feed(html)
    parser.close()
    text = "".join(parser.parts)
    return text if parser.found and text else None
```

This preserves whitespace in the element’s text; whitespace-only text is not considered empty.

