import csv
import re
from datetime import date
from io import StringIO


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    def parse_bound(value):
        if not isinstance(value, str) or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value):
            raise ValueError(f"Invalid date: {value!r}")
        return date.fromisoformat(value)

    start = parse_bound(start_date)
    end = parse_bound(end_date)

    rows = csv.reader(StringIO(csv_text))
    header = next(rows, [])
    if column_name not in header:
        raise ValueError(f"Column not found: {column_name!r}")

    index = header.index(column_name)
    return [
        row for row in rows
        if len(row) > index and start <= date.fromisoformat(row[index]) <= end
    ]
