            raise ValueError(f"Invalid date bound: {bound!r}") from None

    rows = csv.reader(StringIO(csv_text))
    header = next(rows, [])

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column not found: {column_name!r}") from None

