import csv
import io

import numpy as np


def predict_linear_regression(train_csv, test_csv, target):
    def read_csv(text):
        rows = csv.reader(io.StringIO(text))
        header = next(rows, None)
        if not header or len(header) != len(set(header)):
            raise ValueError("CSV must have a header with unique column names")

        data = list(rows)
        if any(len(row) != len(header) for row in data):
            raise ValueError("CSV row has the wrong number of values")
        return header, data

    train_header, train_rows = read_csv(train_csv)
    test_header, test_rows = read_csv(test_csv)

    if target not in train_header or set(train_header) != set(test_header):
        raise ValueError("Target or CSV columns do not match")
    if not train_rows:
        raise ValueError("Training CSV has no data rows")

    features = [name for name in train_header if name != target]

    def numeric(row, header, name):
        value = row[header.index(name)]
        try:
            number = float(value)
        except ValueError as exc:
            raise ValueError(f"Missing or non-numeric value in {name}") from exc
        if not np.isfinite(number):
            raise ValueError(f"Missing or non-numeric value in {name}")
        return number

    def design_matrix(rows, header):
        return np.array(
            [[1.0] + [numeric(row, header, name) for name in features]
             for row in rows],
            dtype=float,
        ).reshape(len(rows), len(features) + 1)

    X = design_matrix(train_rows, train_header)
    y = np.array(
        [numeric(row, train_header, target) for row in train_rows]
    )
    coefficients = np.linalg.lstsq(X, y, rcond=None)[0]

    return (design_matrix(test_rows, test_header) @ coefficients).tolist()
