import csv
import io
import math

import numpy as np


def predict_linear_regression(train_csv, test_csv, target):
    def read_csv(text):
        reader = csv.DictReader(io.StringIO(text))
        return reader.fieldnames, list(reader)

    def number(value):
        try:
            result = float(value)
        except (TypeError, ValueError):
            raise ValueError("Missing or non-numeric value") from None
        if not math.isfinite(result):
            raise ValueError("Missing or non-numeric value")
        return result

    train_columns, train_rows = read_csv(train_csv)
    test_columns, test_rows = read_csv(test_csv)

    if not train_columns or target not in train_columns:
        raise ValueError("Target column not found")
    if test_columns is None or set(test_columns) != set(train_columns):
        raise ValueError("CSV columns do not match")
    if not train_rows:
        raise ValueError("Training CSV has no data rows")

    features = [column for column in train_columns if column != target]

    x_train = np.array(
        [[1.0] + [number(row[column]) for column in features]
         for row in train_rows],
        dtype=float,
    )
    y_train = np.array([number(row[target]) for row in train_rows])
    coefficients, *_ = np.linalg.lstsq(x_train, y_train, rcond=None)

    x_test = np.array(
        [[1.0] + [number(row[column]) for column in features]
         for row in test_rows],
        dtype=float,
    ).reshape(-1, len(features) + 1)

    return (x_test @ coefficients).tolist()
