        reader = csv.reader(io.StringIO(text))
        header = next(reader, None)
        if not header or len(header) != len(set(header)):
            raise ValueError("CSV must have a header with unique column names")
        rows = list(reader)
        if any(len(row) != len(header) for row in rows):
            raise ValueError("CSV row has missing or extra values")
        return header, rows

    def numeric(value):
        try:
            result = float(value)
        except ValueError as exc:
            raise ValueError("Missing or non-numeric value") from exc
        if not math.isfinite(result):
            raise ValueError("Missing or non-numeric value")
        return result

    train_header, train_rows = read_csv(train_csv)
    test_header, test_rows = read_csv(test_csv)

    if target not in train_header or set(train_header) != set(test_header):
        raise ValueError("Target not found or CSV columns do not match")
    if not train_rows:
        raise ValueError("Training CSV has no data rows")

    features = [name for name in train_header if name != target]
    train_index = {name: i for i, name in enumerate(train_header)}
    test_index = {name: i for i, name in enumerate(test_header)}

    X = np.array(
        [[1.0] + [numeric(row[train_index[name]]) for name in features]
         for row in train_rows]
    )
    y = np.array([numeric(row[train_index[target]]) for row in train_rows])

    coefficients, *_ = np.linalg.lstsq(X, y, rcond=None)

    return [
        float(np.dot(
            [1.0] + [numeric(row[test_index[name]]) for name in features],
            coefficients,
        ))
        for row in test_rows
    ]
