        try:
            value = float(row[column])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Missing or non-numeric value in {column!r}") from exc
        if not np.isfinite(value):
            raise ValueError(f"Missing or non-numeric value in {column!r}")
        return value

    if not train_rows:
        raise ValueError("Training CSV must contain at least one row")

    x_train = np.array(
        [[1.0] + [numeric(row, column) for column in features]
         for row in train_rows]
    )
    y_train = np.array([numeric(row, target) for row in train_rows])

    # Least squares also handles cases where the coefficients are not unique.
    coefficients, *_ = np.linalg.lstsq(x_train, y_train, rcond=None)

    x_test = np.array(
        [[1.0] + [numeric(row, column) for column in features]
