from math import fsum, sqrt

def standardize_columns(data):
    result = {}

    for name, values in data.items():
        present = [value for value in values if value is not None]
        if not present:
            raise ValueError(f"Column {name!r} has no present values")

        fill_value = fsum(present) / len(present)
        filled = [fill_value if value is None else value for value in values]

        mean = fsum(filled) / len(filled)
        std = sqrt(fsum((value - mean) ** 2 for value in filled) / len(filled))

        result[name] = (
            [(value - mean) / std for value in filled]
            if std != 0
            else [0.0] * len(filled)
        )

    return result
