from html.parser import HTMLParser


def extract_data_table_rows(html):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.table_depth = 0
            self.done = False
            self.row = None
            self.cell = None

        def finish_cell(self):
            if self.cell is not None:
                self.row.append("".join(self.cell))
                self.cell = None

        def finish_row(self):
            if self.row is not None:
                self.finish_cell()
                self.rows.append(self.row)
                self.row = None

        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            if tag == "table":
                if self.table_depth:
                    self.table_depth += 1
                elif dict(attrs).get("class") == "data-table":
                    self.table_depth = 1
            elif self.table_depth == 1:
                if tag == "tr":
                    self.finish_row()
                    self.row = []
                elif tag == "td" and self.row is not None:
                    self.finish_cell()
                    self.cell = []

        def handle_endtag(self, tag):
            if self.done or not self.table_depth:
                return

            if tag == "table":
                if self.table_depth == 1:
                    self.finish_row()
                    self.done = True
                self.table_depth -= 1
            elif self.table_depth == 1:
                if tag == "td":
                    self.finish_cell()
                elif tag == "tr":
                    self.finish_row()

        def handle_data(self, data):
            if self.cell is not None:
                self.cell.append(data)

    parser = TableParser()
    parser.feed(html)
    parser.finish_row()
    return parser.rows
