        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            if tag == "table":
                if self.table_depth:
                    self.table_depth += 1
                elif dict(attrs).get("class") == "data-table":
                    self.table_depth = 1
            elif self.table_depth == 1:
                if tag == "tr":
                    self.row = []
                elif tag == "td" and self.row is not None:
                    self.cell = []

        def handle_data(self, data):
            if self.cell is not None:
                self.cell.append(data)

        def handle_endtag(self, tag):
            if not self.table_depth or self.done:
                return

            if tag == "table":
                self.table_depth -= 1
                if self.table_depth == 0:
                    self._finish_row()
                    self.done = True
            elif self.table_depth == 1:
                if tag == "td":
                    self._finish_cell()
                elif tag == "tr":
                    self._finish_row()

        def _finish_cell(self):
            if self.cell is not None:
                self.row.append("".join(self.cell))
                self.cell = None

        def _finish_row(self):
            if self.row is not None:
                self._finish_cell()
                self.rows.append(self.row)
                self.row = None

    parser = TableParser()
    parser.feed(html)
    parser.close()
    return parser.rows
