                cells = []
                for row in self.open_rows:
                    cell = []
                    row.append(cell)
                    cells.append(cell)
                self.open_cells.append(cells)

        def handle_data(self, data):
            if not self.finished:
                for cells in self.open_cells:
                    for cell in cells:
                        cell.append(data)

        def handle_endtag(self, tag):
            if self.finished:
                return

            if self.target_depth is not None:
                if tag == "td" and self.open_cells:
                    self.open_cells.pop()
                elif tag == "tr" and self.open_rows:
                    self.open_rows.pop()

            if tag == "table":
                if self.table_depth == self.target_depth:
                    self.finished = True
                self.table_depth -= 1

