from html.parser import HTMLParser


def extract_data_table_rows(html):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.tags = []
            self.table_depth = None
            self.done = False
            self.rows = []
            self.open_rows = []
            self.open_cells = []

        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            self.tags.append(tag)
            depth = len(self.tags)

            if self.table_depth is None:
                if tag == "table" and any(
                    name == "class" and value == "data-table"
                    for name, value in attrs
                ):
                    self.table_depth = depth
                return

            if tag == "tr":
                row = []
                self.rows.append(row)
                self.open_rows.append((depth, row))
            elif tag == "td" and self.open_rows:
                text_parts = []
                self.open_rows[-1][1].append(text_parts)
                self.open_cells.append((depth, text_parts))

        def handle_data(self, data):
            if self.open_cells:
                self.open_cells[-1][1].append(data)

        def handle_endtag(self, tag):
            if self.done or tag not in self.tags:
                return

            # Remove the matching element and anything left open inside it.
            match = len(self.tags) - 1 - self.tags[::-1].index(tag)
            del self.tags[match:]
            depth = len(self.tags)

            while self.open_cells and self.open_cells[-1][0] > depth:
                self.open_cells.pop()
            while self.open_rows and self.open_rows[-1][0] > depth:
                self.open_rows.pop()

            if self.table_depth is not None and depth < self.table_depth:
                self.done = True

    parser = TableParser()
    parser.feed(html)
    parser.close()
    return [[
        "".join(text_parts) for text_parts in row
    ] for row in parser.rows]
