def extract_data_table_rows(html):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.depth = 0
            self.done = False
            self.rows = []
            self.row = None
            self.cell = None

        def end_cell(self):
            if self.cell is not None:
                self.row.append("".join(self.cell))
                self.cell = None

        def end_row(self):
            if self.row is not None:
                self.end_cell()
                self.rows.append(self.row)
                self.row = None

        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            if tag == "table":
                if self.depth:
                    self.depth += 1
                elif dict(attrs).get("class") == "data-table":
                    self.depth = 1
            elif self.depth == 1:
                if tag == "tr":
                    self.end_row()
                    self.row = []
                elif tag == "td" and self.row is not None:
                    self.end_cell()
                    self.cell = []

        def handle_endtag(self, tag):
            if self.done or not self.depth:
                return

            if tag == "table":
                self.depth -= 1
                if self.depth == 0:
                    self.end_row()
                    self.done = True
            elif self.depth == 1:
                if tag == "td":
                    self.end_cell()
                elif tag == "tr":
                    self.end_row()

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

        def handle_data(self, data):
            if self.cell is not None:
                self.cell.append(data)

    parser = TableParser()
    parser.feed(html)
    parser.close()
    if not parser.done:
        parser.end_row()  # Include a row if the HTML ends before </table>.
    return parser.rows
