def min_max_scale_columns(data, columns):
    columns = set(columns)
    result = {}

    for name, values in data.items():
        if name not in columns or not values:
            result[name] = values.copy()
            continue

        minimum = min(values)
        maximum = max(values)
        if minimum == maximum:
            result[name] = [0.0 for _ in values]
        else:
            result[name] = [
                (value - minimum) / (maximum - minimum)
                for value in values
            ]

    return result
```

