from math import fsum, sqrt

def standardize_columns(rows, columns):
    result = {}

    for i, name in enumerate(columns):
        values = [row[i] for row in rows]
        if not values:
            result[name] = []
            continue

        mean = fsum(values) / len(values)
        std = sqrt(fsum((value - mean) ** 2 for value in values) / len(values))
        result[name] = (
            [(value - mean) / std for value in values]
            if std != 0
            else [0.0] * len(values)
        )

    return result
