def fit_quadratic(xs, ys):
    if len(xs) != len(ys) or len(xs) < 3:
        raise ValueError("xs and ys must have equal lengths of at least three")

    # Normal equations for the least-squares fit.
    powers = [sum(x**k for x in xs) for k in range(5)]
    rhs = [sum((x**k) * y for x, y in zip(xs, ys)) for k in (2, 1, 0)]
    matrix = [
        [powers[4], powers[3], powers[2], rhs[0]],
        [powers[3], powers[2], powers[1], rhs[1]],
        [powers[2], powers[1], powers[0], rhs[2]],
    ]

    # Solve the 3×3 system by Gaussian elimination.
    for col in range(3):
        pivot = max(range(col, 3), key=lambda row: abs(matrix[row][col]))
        if matrix[pivot][col] == 0:
            raise ValueError("at least three distinct x values are required")
        matrix[col], matrix[pivot] = matrix[pivot], matrix[col]

        divisor = matrix[col][col]
        matrix[col] = [value / divisor for value in matrix[col]]

        for row in range(3):
            if row != col:
                factor = matrix[row][col]
                matrix[row] = [
                    value - factor * pivot_value
                    for value, pivot_value in zip(matrix[row], matrix[col])
                ]

    return [float(matrix[row][3]) for row in range(3)]
