def detect_iqr_outliers(reference, values):
    if not reference:
        return []

    sorted_ref = sorted(reference)

    def quartile(p):
        position = (len(sorted_ref) - 1) * p
        lower = int(position)
        fraction = position - lower
        if fraction == 0:
            return sorted_ref[lower]
        return sorted_ref[lower] + fraction * (
            sorted_ref[lower + 1] - sorted_ref[lower]
        )

    q1 = quartile(0.25)
    q3 = quartile(0.75)
    iqr = q3 - q1
    low, high = q1 - 1.5 * iqr, q3 + 1.5 * iqr

    return [float(x) for x in reference + values if x < low or x > high]
