def seasonal_decomposition(values, period, model):
    values = list(values)
    n = len(values)

    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    trend = [None] * n
    half = period // 2

    for i in range(half, n - half):
        window = values[i - half:i + half + 1]
        if period % 2:
            trend[i] = sum(window) / period
        else:
            trend[i] = (
                sum(window[1:-1]) + (window[0] + window[-1]) / 2
            ) / period

    by_phase = [[] for _ in range(period)]
    for i, t in enumerate(trend):
        if t is None:
            continue
        if model == "additive":
            by_phase[i % period].append(values[i] - t)
        else:
            if t == 0:
                raise ValueError("multiplicative decomposition requires nonzero trends")
            by_phase[i % period].append(values[i] / t)

    indices = [sum(phase) / len(phase) for phase in by_phase]
    average = sum(indices) / period

    if model == "additive":
        indices = [index - average for index in indices]
    else:
        if average == 0:
            raise ValueError("multiplicative seasonal indices cannot be normalised")
        indices = [index / average for index in indices]

    seasonal = [indices[i % period] for i in range(n)]
    residual = [None] * n
    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                residual[i] = values[i] - t - seasonal[i]
            else:
                if seasonal[i] == 0:
                    raise ValueError("multiplicative residual requires nonzero seasonality")
                residual[i] = values[i] / (t * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
