def seasonal_decomposition(values, period, model):
    """Classical decomposition using a centered moving-average trend."""
    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    moving_averages = [
        sum(values[start:start + period]) / period
        for start in range(n - period + 1)
    ]

    trend = [None] * n
    if period % 2:
        for start, average in enumerate(moving_averages):
            trend[start + period // 2] = average
    else:
        for start in range(len(moving_averages) - 1):
            trend[start + period // 2] = (
                moving_averages[start] + moving_averages[start + 1]
            ) / 2

    by_phase = [[] for _ in range(period)]
    for i, t in enumerate(trend):
        if t is None:
            continue
        if model == "additive":
            by_phase[i % period].append(values[i] - t)
        else:
            if t == 0:
                raise ValueError("multiplicative decomposition requires nonzero trend")
            by_phase[i % period].append(values[i] / t)

    indices = [sum(group) / len(group) for group in by_phase]
    if model == "additive":
        offset = sum(indices) / period
        indices = [index - offset for index in indices]
    else:
        mean = sum(indices) / period
        if mean == 0:
            raise ValueError("multiplicative seasonal indices cannot be normalized")
        indices = [index / mean for index in indices]

    seasonal = [indices[i % period] for i in range(n)]
    residual = [None] * n
    for i, t in enumerate(trend):
        if t is None:
            continue
        if model == "additive":
            residual[i] = values[i] - t - seasonal[i]
        else:
            denominator = t * seasonal[i]
            if denominator == 0:
                raise ValueError("multiplicative residual requires nonzero components")
            residual[i] = values[i] / denominator

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
