def seasonal_decomposition(values, period, model):
    values = list(values)
    n = len(values)

    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    trend = [None] * n
    half = period // 2

    if period % 2:  # Odd period: the moving average is already centered.
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:  # Even period: average two adjacent moving averages.
        for i in range(half, n - half):
            left = sum(values[i - half:i + half]) / period
            right = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (left + right) / 2

    phase_values = [[] for _ in range(period)]
    for i, t in enumerate(trend):
        if t is None:
            continue
        if model == "additive":
            phase_values[i % period].append(values[i] - t)
        else:
            if t == 0:
                raise ValueError("multiplicative decomposition requires nonzero trend values")
            phase_values[i % period].append(values[i] / t)

    indices = [sum(group) / len(group) for group in phase_values]
    mean_index = sum(indices) / period

    if model == "additive":
        indices = [index - mean_index for index in indices]
    else:
        if mean_index == 0:
            raise ValueError("multiplicative seasonal indices cannot be normalized")
        indices = [index / mean_index for index in indices]

    seasonal = [indices[i % period] for i in range(n)]
    residual = [None] * n
    for i, t in enumerate(trend):
        if t is not None:
            residual[i] = (
                values[i] - t - seasonal[i]
                if model == "additive"
                else values[i] / (t * seasonal[i])
                if seasonal[i] != 0
                else None
            )

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
