        if all(value is not None for value in row):
            for name, value in zip(data, row):
                cleaned[name].append(value)

    result = {}
    for name, values in cleaned.items():
        if not values:
            result[name] = []
            continue

        low, high = min(values), max(values)
        result[name] = (
            [0.0] * len(values) if low == high
            else [(value - low) / (high - low) for value in values]
        )

    return result
```

