            "mean": None,
            "min": None,
            "max": None,
            "histogram": [0] * 10,
        }

    minimum, maximum = min(values), max(values)
    histogram = [0] * 10

    for value in values:
        if minimum == maximum:
            bin_index = 0
        else:
            bin_index = min(9, int(10 * (value - minimum) / (maximum - minimum)))
        histogram[bin_index] += 1

    return {
        "sum": sum(values),
        "mean": sum(values) / len(values),
        "min": minimum,
        "max": maximum,
        "histogram": histogram,
    }
