from collections import Counter, defaultdict

def association_chi_square(left, right):
    right_by_id = defaultdict(list)
    for id_, category in right:
        right_by_id[id_].append(category)

    counts = Counter()
    left_totals = Counter()
    right_totals = Counter()

    for id_, left_category in left:
        for right_category in right_by_id.get(id_, ()):
            counts[left_category, right_category] += 1
            left_totals[left_category] += 1
            right_totals[right_category] += 1

    total = sum(counts.values())
    if total == 0:
        return (0.0, 0)

    statistic = 0.0
    for left_category, left_total in left_totals.items():
        for right_category, right_total in right_totals.items():
            expected = left_total * right_total / total
            observed = counts[left_category, right_category]
            statistic += (observed - expected) ** 2 / expected

    dof = (len(left_totals) - 1) * (len(right_totals) - 1)
    return (statistic, dof)
```

If an id appears multiple times in either list, this uses all matching pairs, as a join does.

