from collections import Counter, defaultdict

def association_chi_square(left, right):
    """Return the Pearson chi-square statistic and degrees of freedom."""
    right_by_id = defaultdict(list)
    for id_, category in right:
        right_by_id[id_].append(category)

    counts = Counter()
    for id_, left_category in left:
        for right_category in right_by_id.get(id_, ()):
            counts[left_category, right_category] += 1

    if not counts:
        raise ValueError("The lists have no matching ids")

    row_totals = Counter()
    col_totals = Counter()
    for (left_category, right_category), count in counts.items():
        row_totals[left_category] += count
        col_totals[right_category] += count

    total = sum(counts.values())
    statistic = sum(
        (counts[row, col] - row_count * col_count / total) ** 2
        / (row_count * col_count / total)
        for row, row_count in row_totals.items()
        for col, col_count in col_totals.items()
    )
    dof = (len(row_totals) - 1) * (len(col_totals) - 1)
    return statistic, dof
```

If an id occurs more than once in either list, each matching pair contributes a joined record.

