        hour = published.astimezone(target_zone).hour
        hours_by_category[article["category"]].append(hour)

    return {
        category: {
            "count": len(hours),
            "mean": sum(hours) / len(hours),
            "min": min(hours),
            "max": max(hours),
        }
        for category, hours in hours_by_category.items()
    }
