from math import sqrt

def zscore_normalize_columns(matrix):
    if not matrix:
        return []

    result = [[0.0] * len(matrix[0]) for _ in matrix]
    n = len(matrix)

    for col in range(len(matrix[0])):
        mean = sum(row[col] for row in matrix) / n
        std = sqrt(sum((row[col] - mean) ** 2 for row in matrix) / n)

        if std != 0:
            for i, row in enumerate(matrix):
                result[i][col] = (row[col] - mean) / std

    return result
