from bisect import bisect_right

def salary_histogram(salaries_by_dept, dept):
    salaries = salaries_by_dept[dept]
    if not salaries:
        raise ValueError("The department has no salaries")

    lowest, highest = min(salaries), max(salaries)
    if lowest == highest:
        raise ValueError("Cannot make 10 equal-width bins from identical salaries")

    edges = [
        float(lowest + (highest - lowest) * i / 10)
        for i in range(11)
    ]
    counts = [0] * 10

    for salary in salaries:
        bin_index = min(bisect_right(edges, salary) - 1, 9)
        counts[bin_index] += 1

    return counts, edges
