from collections import Counter
from sklearn.cluster import KMeans


def cluster_unique_points(points, n_clusters):
    if n_clusters < 1:
        raise ValueError("n_clusters must be positive")

    counts = Counter(map(tuple, points))
    duplicates = {point: count for point, count in counts.items() if count > 1}
    unique_points = sorted(counts)

    if not unique_points:
        return duplicates, []

    k = min(n_clusters, len(unique_points))
    if k == len(unique_points):
        return duplicates, [[point] for point in unique_points]

    labels = KMeans(n_clusters=k, random_state=0, n_init=10).fit_predict(
        unique_points
    )
    clusters = [[] for _ in range(k)]
    for point, label in zip(unique_points, labels):
        clusters[label].append(point)

    return duplicates, sorted(sorted(cluster) for cluster in clusters if cluster)
