import math

def column_correlations(data):
    names = list(data)
    if not names:
        return {}

    centered = {}
    lengths = {len(values) for values in data.values()}
    if len(lengths) != 1:
        raise ValueError("Columns must have equal lengths")

    for name, values in data.items():
        if not values:
            raise ValueError("Columns must not be empty")
        mean = math.fsum(values) / len(values)
        deviations = [value - mean for value in values]
        if math.fsum(d * d for d in deviations) == 0:
            raise ValueError(f"Pearson correlation is undefined for constant column {name!r}")
        centered[name] = deviations

    result = {name: {} for name in names}
    for i, x in enumerate(names):
        result[x][x] = 1.0
        dx = centered[x]
        sx = math.sqrt(math.fsum(d * d for d in dx))
