import math

def column_correlations(data):
    """Return a nested dict of pairwise Pearson correlations."""
    if not data:
        return {}

    names = list(data)
    n = len(data[names[0]])
    if n < 2:
        raise ValueError("Correlation requires at least two values per column")

    centered = {}
    sums_of_squares = {}
    for name in names:
        values = data[name]
        mean = math.fsum(values) / n
        deviations = [value - mean for value in values]
        squared_sum = math.fsum(d * d for d in deviations)
        if squared_sum == 0:
            raise ValueError(f"Correlation is undefined for constant column {name!r}")
        centered[name] = deviations
        sums_of_squares[name] = squared_sum

    result = {name: {name: 1.0} for name in names}
    for i, x in enumerate(names):
        for y in names[i + 1:]:
            numerator = math.fsum(a * b for a, b in zip(centered[x], centered[y]))
            correlation = numerator / math.sqrt(sums_of_squares[x] * sums_of_squares[y])
            result[x][y] = result[y][x] = correlation

    return result
