from math import sqrt

def describe_filled_columns(columns):
    def percentile(sorted_values, p):
        position = (len(sorted_values) - 1) * p
        lower = int(position)
        fraction = position - lower
        if fraction == 0:
            return sorted_values[lower]
        return (sorted_values[lower] * (1 - fraction)
                + sorted_values[lower + 1] * fraction)

    result = {}

    for name, values in columns.items():
        present = [float(value) for value in values if value is not None]
        if not present:
            raise ValueError(f"Column {name!r} has no present values")

        fill_value = sum(present) / len(present)
        filled = sorted(
            fill_value if value is None else float(value)
            for value in values
        )
        count = len(filled)
        mean = sum(filled) / count

        result[name] = {
            "count": float(count),
            "mean": mean,
            "std": (
                sqrt(sum((value - mean) ** 2 for value in filled) / (count - 1))
                if count > 1 else float("nan")
            ),
            "min": filled[0],
            "25%": percentile(filled, 0.25),
            "50%": percentile(filled, 0.50),
            "75%": percentile(filled, 0.75),
            "max": filled[-1],
        }

    return result
