import math

def spectrum_magnitude_histogram(pairs):
    values = [value for _, value in pairs]
    n = len(values)
    if n == 0:
        return [], []

    magnitudes = [
        abs(sum(
            value * cmath.exp(-2j * math.pi * k * j / n)
            for j, value in enumerate(values)
        ))
        for k in range(n)
    ]

    counts = [0] * 10
    smallest, largest = min(magnitudes), max(magnitudes)

    if smallest == largest:
        counts[0] = n
    else:
        width = (largest - smallest) / 10
        for magnitude in magnitudes:
            bin_index = min(int((magnitude - smallest) / width), 9)
            counts[bin_index] += 1

    return magnitudes, counts
