import math


def spectrum_magnitude_histogram(pairs):
    """Return DFT magnitudes and a 10-bin histogram of those magnitudes."""
    if not pairs:
        return [], []

    values = [value for _, value in pairs]
    n = len(values)
    magnitudes = []

    for k in range(n):
        real = math.fsum(
            value * math.cos(2 * math.pi * k * j / n)
            for j, value in enumerate(values)
        )
        imag = math.fsum(
            -value * math.sin(2 * math.pi * k * j / n)
            for j, value in enumerate(values)
        )
        magnitudes.append(math.hypot(real, imag))

    low, high = min(magnitudes), max(magnitudes)
    counts = [0] * 10

    if low == high:
        counts[0] = n
    else:
        width = (high - low) / 10
        for magnitude in magnitudes:
            bin_index = min(9, int((magnitude - low) / width))
            counts[bin_index] += 1

    return magnitudes, counts
```

