from numbers import Real

def normalized_cumulative_sums(data):
    if not data:
        raise ValueError("data must not be empty")

    result = {}

    for name, values in data.items():
        cumulative = []
        total = 0

        for value in values:
            if not isinstance(value, Real):
                raise TypeError(f"Column {name!r} contains a non-numeric value")
            if value != value:  # NaN is not equal to itself
                raise ValueError(f"Column {name!r} contains NaN")

            total += value
            cumulative.append(total)

        if not cumulative:
            result[name] = []
            continue

        minimum, maximum = min(cumulative), max(cumulative)
        span = maximum - minimum
        result[name] = (
            [(value - minimum) / span for value in cumulative]
            if span
            else [0.0] * len(cumulative)
        )

    return result
```

