from statistics import mean, pstdev


def standardize_by_group(records):
    groups = defaultdict(list)

    for record in records:
        if not all(key in record for key in ("id", "age", "income")):
            raise ValueError("Each record must have 'id', 'age', and 'income'")
        groups[record["id"]].append(record)

    stats = {}
    for group_id, group in groups.items():
        stats[group_id] = {}
        for field in ("age", "income"):
            values = [record[field] for record in group]
            stats[group_id][field] = (mean(values), pstdev(values))

    result = []
    for record in records:
        standardized = {"id": record["id"]}
        for field in ("age", "income"):
            average, std_dev = stats[record["id"]][field]
            standardized[field] = (
                float((record[field] - average) / std_dev) if std_dev else 0.0
            )
        result.append(standardized)

    return result
