import xml.etree.ElementTree as ET


def xml_to_dict(xml):
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML") from exc

    def convert(element):
        children = list(element)
        text = "".join(
            [element.text or ""] + [child.tail or "" for child in children]
        ).strip()

        if not element.attrib and not children:
            return text or None

        result = {f"@{key}": value for key, value in element.attrib.items()}
        if text:
            result["#text"] = text

        repeated = set()
        for child in children:
            tag = child.tag
            value = convert(child)
            if tag in repeated:
                result[tag].append(value)
            elif tag in result:
                result[tag] = [result[tag], value]
                repeated.add(tag)
            else:
                result[tag] = value

        return result

    return {root.tag: convert(root)}
