            return element.text.strip() if element.text is not None else None

        result = {f"@{key}": value for key, value in element.attrib.items()}

        for child in children:
            value = convert(child)
            tag = child.tag
            if tag not in result:
                result[tag] = value
            elif isinstance(result[tag], list):
                result[tag].append(value)
            else:
                result[tag] = [result[tag], value]

        # Include text directly inside this element, including text after children.
        text = "".join(
            part for part in [element.text, *(child.tail for child in children)]
            if part is not None
        ).strip()
        if text:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
