            return element.text.strip() if element.text is not None else None

        result = {f"@{key}": value for key, value in element.attrib.items()}
        counts = Counter(child.tag for child in children)

        for child in children:
            value = convert(child)
            if counts[child.tag] > 1:
                result.setdefault(child.tag, []).append(value)
            else:
                result[child.tag] = value

        # Include this element's own text and text following its children,
        # but not text inside those children.
        text = "".join(
            [element.text or ""] + [child.tail or "" for child in children]
        ).strip()
        if text:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
