import math
from numbers import Real


def row_averages_and_correlations(data):
    if not isinstance(data, list) or len(data) < 2:
        raise ValueError("data must be a list of at least two rows")

    width = len(data[0]) if isinstance(data[0], list) else 0
    if width == 0:
        raise ValueError("rows must be nonempty lists")

    for row in data:
        if (
            not isinstance(row, list)
            or len(row) != width
            or any(
                isinstance(x, bool)
                or not isinstance(x, Real)
                or not math.isfinite(x)
                for x in row
            )
        ):
            raise ValueError("data must be a rectangular list of finite numbers")

    averages = [math.fsum(row) / width for row in data]

    columns = list(zip(*data))
    centered = [
        [x - math.fsum(column) / len(column) for x in column]
        for column in columns
    ]
    lengths = [math.hypot(*column) for column in centered]
    if any(length == 0 for length in lengths):
        raise ValueError("correlation is undefined for a constant column")

    corr = [[1.0 if i == j else 0.0 for j in range(width)]
            for i in range(width)]
    for i in range(width):
        for j in range(i + 1, width):
            value = math.fsum(
                (x / lengths[i]) * (y / lengths[j])
                for x, y in zip(centered[i], centered[j])
            )
            corr[i][j] = corr[j][i] = value

    return averages, corr
```

Pearson correlation is undefined with fewer than two rows or with a constant column, so the function raises `ValueError` in those cases.

