import math
from numbers import Real


def row_averages_and_correlations(data):
    if not isinstance(data, list) or len(data) < 2:
        raise ValueError("data must be a list of at least two rows")
    if not all(isinstance(row, list) for row in data):
        raise ValueError("each row must be a list")

    width = len(data[0])
    if width == 0 or any(len(row) != width for row in data):
        raise ValueError("data must be rectangular and have at least one column")

    for row in data:
        for value in row:
            if (
                isinstance(value, bool)
                or not isinstance(value, Real)
                or not math.isfinite(value)
            ):
                raise ValueError("all values must be finite real numbers")

    averages = [math.fsum(row) / width for row in data]

    columns = list(zip(*data))
    centered = []
    for column in columns:
        mean = math.fsum(column) / len(column)
        centered.append([value - mean for value in column])

    squared_norms = [math.fsum(x * x for x in col) for col in centered]
    if any(norm == 0 for norm in squared_norms):
        raise ValueError("Pearson correlation is undefined for a constant column")

    corr = [[0.0] * width for _ in range(width)]
    for i in range(width):
        corr[i][i] = 1.0
        for j in range(i + 1, width):
            numerator = math.fsum(
                x * y for x, y in zip(centered[i], centered[j])
            )
            value = numerator / math.sqrt(squared_norms[i] * squared_norms[j])
            corr[i][j] = corr[j][i] = max(-1.0, min(1.0, value))

    return averages, corr
```

At least two rows and a nonconstant value in every column are required because Pearson correlation is otherwise undefined.

