import math
from numbers import Real


def row_averages_and_correlations(data):
    if not isinstance(data, list) or not data:
        raise ValueError("data must be a nonempty list of rows")

    width = None
    rows = []
    for row in data:
        if not isinstance(row, list) or not row:
            raise ValueError("each row must be a nonempty list of numbers")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("rows must have equal lengths")

        converted = []
        for value in row:
            if not isinstance(value, Real) or isinstance(value, bool):
                raise ValueError("all entries must be real numbers")
            try:
                number = float(value)
            except (OverflowError, ValueError) as exc:
                raise ValueError("all entries must be finite numbers") from exc
            if not math.isfinite(number):
                raise ValueError("all entries must be finite numbers")
            converted.append(number)
        rows.append(converted)

    averages = [math.fsum(row) / width for row in rows]

    if len(rows) < 2:
        raise ValueError("correlation requires at least two rows")

    columns = list(zip(*rows))
    centered = [
        [x - math.fsum(column) / len(rows) for x in column]
        for column in columns
    ]
    sum_squares = [math.fsum(x * x for x in column) for column in centered]
    if any(total == 0 for total in sum_squares):
        raise ValueError("correlation is undefined for a constant column")

    corr = [[1.0 if i == j else 0.0 for j in range(width)]
            for i in range(width)]
    for i in range(width):
        for j in range(i + 1, width):
            numerator = math.fsum(x * y for x, y in zip(centered[i], centered[j]))
            value = numerator / math.sqrt(sum_squares[i] * sum_squares[j])
            corr[i][j] = corr[j][i] = value

    return averages, corr
```

An empty table, an empty row, fewer than two rows, or a constant column raises `ValueError` because the requested means or correlations would be undefined.

