def interquartile_range_nested(L):
    values = sorted(number for row in L for number in row)
    if not values:
        raise ValueError("L must contain at least one number")

    def percentile(p):
        position = (len(values) - 1) * p
        lower = int(position)
        fraction = position - lower
        if fraction == 0:
            return float(values[lower])
        return float(values[lower] + fraction * (values[lower + 1] - values[lower]))

    return percentile(0.75) - percentile(0.25)
