    if not P or not T or not P[0] or not T[0] or not T[0][0]:
        raise ValueError("P and T must be nonempty")

    m, k = len(P), len(P[0])
    if k != len(T):
        raise ValueError("P's column count must match T's first dimension")

    n, p = len(T[0]), len(T[0][0])
    if any(len(row) != k for row in P) or any(
        len(layer) != n or any(len(row) != p for row in layer)
        for layer in T
    ):
        raise ValueError("P and T must have consistent dimensions")

    table = [
        [
            float(fsum(P[i][a] * T[a][j][b] for a in range(k)))
            for i in range(m)
            for b in range(p)
        ]
        for j in range(n)
    ]

    for col in range(m * p):
        mean = fsum(row[col] for row in table) / n
        std = sqrt(fsum((row[col] - mean) ** 2 for row in table) / n)
        for row in table:
            row[col] = (row[col] - mean) / std if std else 0.0

    return table
```

