from math import fsum, sqrt

def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must be nonempty")

    m, k = len(P), len(P[0])
    if k != len(T):
        raise ValueError("P's number of columns must match T's first dimension")
    if any(len(row) != k for row in P):
        raise ValueError("P must be rectangular")

    n = len(T[0])
    if n == 0 or not T[0][0]:
        raise ValueError("T must have nonempty second and third dimensions")
    p = len(T[0][0])
    if any(len(layer) != n or any(len(row) != p for row in layer)
           for layer in T):
        raise ValueError("T must be rectangular")

    table = [
        [
            fsum(P[i][h] * T[h][j][a] for h in range(k))
            for i in range(m)
            for a in range(p)
        ]
        for j in range(n)
    ]

    columns = []
    for column in zip(*table):
        mean = fsum(column) / n
        std = sqrt(fsum((x - mean) ** 2 for x in column) / n)
        columns.append(
            [(x - mean) / std for x in column] if std else [0.0] * n
        )

    return [list(row) for row in zip(*columns)]
