def quartiles_of_string_groups(groups):
    values = sorted(int(item) for group in groups for item in group)
    if not values:
        raise ValueError("At least one integer is required")

    def percentile(quarter):
        index, remainder = divmod((len(values) - 1) * quarter, 4)
        if remainder == 0:
            return float(values[index])
        return float(
            values[index]
            + (values[index + 1] - values[index]) * remainder / 4
        )

    return (percentile(1), percentile(2), percentile(3))
```

