def quartiles_of_string_groups(groups):
    values = sorted(int(value) for group in groups for value in group)
    if not values:
        raise ValueError("Cannot calculate quartiles of an empty collection")

    def percentile(p):
        position = (len(values) - 1) * p
        lower = int(position)
        fraction = position - lower
        upper = min(lower + 1, len(values) - 1)
        return float(values[lower] + fraction * (values[upper] - values[lower]))

    return tuple(percentile(p) for p in (0.25, 0.50, 0.75))
