        else:
            b = bounds[group]
            b[0] = min(b[0], age)
            b[1] = max(b[1], age)
            b[2] = min(b[2], income)
            b[3] = max(b[3], income)

    scaled = []
    counts = [0] * 10

    for group, age, income in zip(ids, ages, incomes):
        min_age, max_age, min_income, max_income = bounds[group]

        def scale(value, low, high):
            if low == high:
                return 0.0
            factor = 1.0 / (high - low)
            return value * factor - low * factor

        scaled_age = scale(age, min_age, max_age)
        scaled_income = scale(income, min_income, max_income)
        scaled.append([scaled_age, scaled_income])

        # Include 1 (and values rounded very near it) in the last bin.
        bin_index = min(9, max(0, int(scaled_income * 10)))
        counts[bin_index] += 1

