import csv
import io


def fill_missing_with_column_mean(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    headers = next(reader, None)
    if headers is None:
        return {}

    columns = {header: [] for header in headers}
    for row in reader:
        for index, header in enumerate(headers):
            columns[header].append(row[index] if index < len(row) else "")

    result = {}
    for header, values in columns.items():
        present = [value for value in values if value != ""]

        if not present:
            result[header] = [None] * len(values)
            continue

        try:
            numbers = [float(value) for value in present]
        except ValueError:
            result[header] = [value if value != "" else None for value in values]
        else:
            mean = sum(numbers) / len(numbers)
            result[header] = [
                float(value) if value != "" else mean for value in values
            ]

    return result
