from statistics import mean, stdev


def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}
    for name, column in data.items():
        values = [replacements.get(value, value) for value in column]

        if any(isinstance(value, str) for value in values):
            codes = {
                value: index
                for index, value in enumerate(sorted(set(values)))
            }
            values = [codes[value] for value in values]

        if len(values) < 2:
            raise ValueError(f"Column {name!r} needs at least two values")

        average = mean(values)
        deviation = stdev(values)  # Sample standard deviation
        if deviation == 0:
            raise ValueError(f"Column {name!r} has zero standard deviation")

        result[name] = [(value - average) / deviation for value in values]

    return result
