    for j in range(m):
        observed = [row[j] for row in rows if row[j] is not None]
        if not observed:
            raise ValueError(f"Column {j} has no observed values")
        means.append(sum(observed) / len(observed))

    filled = [
        [means[j] if value is None else value for j, value in enumerate(row)]
        for row in rows
    ]

    deviations = [
        [row[j] - means[j] for j in range(m)]
        for row in filled
    ]
    stds = [
        sqrt(sum(row[j] ** 2 for row in deviations) / n)
        for j in range(m)
    ]
    if any(std == 0 for std in stds):
        raise ValueError("Cannot standardize a constant column")

    standardized = [
        [row[j] / stds[j] for j in range(m)]
        for row in deviations
    ]

    corr = [[0.0] * m for _ in range(m)]
    for i in range(m):
        corr[i][i] = 1.0
        for j in range(i + 1, m):
            value = sum(row[i] * row[j] for row in standardized) / n
            corr[i][j] = corr[j][i] = value

    return standardized, corr
```

