from math import fsum, sqrt


def standardize_and_correlate(rows):
    if not rows or not rows[0]:
        raise ValueError("The table must have at least one row and one column.")

    n, m = len(rows), len(rows[0])
    if any(len(row) != m for row in rows):
        raise ValueError("All rows must have the same number of columns.")

    means = []
    for j in range(m):
        observed = [row[j] for row in rows if row[j] is not None]
        if not observed:
            raise ValueError(f"Column {j} has no observed values.")
        means.append(fsum(observed) / len(observed))

    filled = [
        [means[j] if value is None else value for j, value in enumerate(row)]
        for row in rows
    ]

    stddevs = [
        sqrt(fsum((row[j] - means[j]) ** 2 for row in filled) / n)
        for j in range(m)
    ]
    if any(sd == 0 for sd in stddevs):
        raise ValueError("Correlation is undefined for a constant column.")

    standardized = [
        [(row[j] - means[j]) / stddevs[j] for j in range(m)]
        for row in filled
    ]
    corr = [
        [
            1.0 if i == j else
            fsum(row[i] * row[j] for row in standardized) / n
            for j in range(m)
        ]
        for i in range(m)
    ]
    return standardized, corr
