def replace_and_standardize(data, features, mapping):
    missing = [name for name in features if name not in data]
    if missing:
        raise ValueError(f"Missing feature columns: {missing}")

    feature_set = set(features)
    result = {}

    for name, values in data.items():
        replaced = [mapping.get(value, value) for value in values]

        if name not in feature_set or not replaced:
            result[name] = replaced
            continue

        mean = sum(replaced) / len(replaced)
        variance = sum((value - mean) ** 2 for value in replaced) / len(replaced)
        std = variance ** 0.5
        result[name] = (
            [(value - mean) / std for value in replaced]
            if std
            else [0.0] * len(replaced)
        )

    return result
