import math
import re
from collections import Counter

def bracket_free_tfidf(texts):
    def outside_brackets(text):
        result = []
        depth = 0
        for char in text:
            if char == "[":
                depth += 1
                result.append(" ")  # Don't join words across a bracketed section.
            elif char == "]" and depth:
                depth -= 1
            elif depth == 0:
                result.append(char)
        return "".join(result)

    counts = [
        Counter(word.lower() for word in re.findall(r"\w{2,}", outside_brackets(text)))
        for text in texts
    ]

    n = len(texts)
    df = Counter(word for count in counts for word in count)
    idf = {word: math.log((1 + n) / (1 + frequency)) + 1
           for word, frequency in df.items()}

    scores = []
    for count in counts:
        weights = {word: frequency * idf[word] for word, frequency in count.items()}
        norm = math.sqrt(sum(weight ** 2 for weight in weights.values()))
        scores.append({word: weight / norm for word, weight in weights.items()})
    return scores
