def normalize_columns(data_dict, data_keys):
    result = {}

    for key in data_keys:
        if key not in data_dict:
            continue

        values = data_dict[key]
        if not values:
            result[key] = []
            continue

        low, high = min(values), max(values)
        result[key] = (
            [0.0] * len(values)
            if low == high
            else [(value - low) / (high - low) for value in values]
        )

    if not result:
        raise ValueError("None of the requested columns were found")

    return result
