def column_histogram(records, column_name):
    if not records or any(column_name not in row for row in records):
        raise ValueError(f"Column {column_name!r} doesn't exist in the table")

    values = [row[column_name] for row in records]
    if isinstance(values[0], str):
        indices = {value: i for i, value in enumerate(sorted(set(values)))}
        values = [indices[value] for value in values]

    minimum, maximum = min(values), max(values)
    counts = [0] * 10

    if minimum == maximum:
        counts[9] = len(values)
    else:
        width = (maximum - minimum) / 10
        for value in values:
            bin_index = min(9, int((value - minimum) / width))
            counts[bin_index] += 1

    return counts
```

