    values = [row[column_name] for row in records]

    if isinstance(values[0], str):
        indices = {value: i for i, value in enumerate(sorted(set(values)))}
        values = [indices[value] for value in values]

    minimum, maximum = min(values), max(values)
    counts = [0] * 10

    if minimum == maximum:
