import json
import math


def boxplot_stats_at_path(json_data, key_path):
    def reject_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        value = json.loads(json_data, parse_constant=reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError("Malformed JSON") from exc

    for key in key_path:
        if not isinstance(value, dict) or key not in value:
            raise KeyError(key)
        value = value[key]

    if not isinstance(value, str) or not value.strip():
        raise ValueError("Data must be a nonempty string of numbers")

    try:
        numbers = sorted(float(part.strip()) for part in value.split(","))
    except ValueError as exc:
        raise ValueError("Data must contain only numbers") from exc

    if not all(math.isfinite(number) for number in numbers):
        raise ValueError("Data must contain only finite numbers")

    def percentile(fraction):
        position = (len(numbers) - 1) * fraction
        lower = int(position)
        upper = min(lower + 1, len(numbers) - 1)
        return numbers[lower] + (numbers[upper] - numbers[lower]) * (position - lower)

    q1 = percentile(0.25)
    median = percentile(0.5)
    q3 = percentile(0.75)
    iqr = q3 - q1
    low_limit = q1 - 1.5 * iqr
    high_limit = q3 + 1.5 * iqr

    within_whiskers = [n for n in numbers if low_limit <= n <= high_limit]
    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": within_whiskers[0],
        "whisker_high": within_whiskers[-1],
        "outliers": [n for n in numbers if n < low_limit or n > high_limit],
    }
