def excess_kurtosis(values):
    if not values:
        raise ValueError("values must not be empty")

    mean = sum(values) / len(values)
    deviations = [value - mean for value in values]
    second_moment = sum(d**2 for d in deviations) / len(values)

    if second_moment == 0:
        raise ValueError("all values are equal")

    fourth_moment = sum(d**4 for d in deviations) / len(values)
    return float(fourth_moment / second_moment**2 - 3)
