def holdout_r_squared(train_x, train_y, test_x, test_y):
    if len(test_x) != len(test_y):
        raise ValueError("test_x and test_y must have the same length")
    if len(test_y) < 2:
        raise ValueError("the test set must contain at least 2 points")
    if len(train_x) != len(train_y) or not train_x:
        raise ValueError("training data must be nonempty and have matching lengths")

    mean_x = sum(train_x) / len(train_x)
    mean_y = sum(train_y) / len(train_y)

    denominator = sum((x - mean_x) ** 2 for x in train_x)
    if denominator == 0:
        raise ValueError("training x values must not all be equal")

    slope = sum(
        (x - mean_x) * (y - mean_y)
        for x, y in zip(train_x, train_y)
    ) / denominator
    intercept = mean_y - slope * mean_x

    test_mean_y = sum(test_y) / len(test_y)
    total_error = sum((y - test_mean_y) ** 2 for y in test_y)
    if total_error == 0:
        raise ValueError("R-squared is undefined when all test y values are equal")

    residual_error = sum(
        (y - (slope * x + intercept)) ** 2
        for x, y in zip(test_x, test_y)
    )
    return 1 - residual_error / total_error, slope, intercept
```

