        raise ValueError("x and y must have matching lengths")
    if len(train_x) < 2:
        raise ValueError("the training set must have at least 2 points")
    if len(test_x) < 2:
        raise ValueError("the test set must have at least 2 points")

    x_mean = fsum(train_x) / len(train_x)
    y_mean = fsum(train_y) / len(train_y)
    x_variation = fsum((x - x_mean) ** 2 for x in train_x)
    if x_variation == 0:
        raise ValueError("training x values must not all be equal")

    slope = fsum(
        (x - x_mean) * (y - y_mean)
        for x, y in zip(train_x, train_y)
    ) / x_variation
    intercept = y_mean - slope * x_mean

    test_mean = fsum(test_y) / len(test_y)
    total_variation = fsum((y - test_mean) ** 2 for y in test_y)
    if total_variation == 0:
        raise ValueError("R-squared is undefined when all test y values are equal")

    squared_error = fsum(
        (y - (slope * x + intercept)) ** 2
        for x, y in zip(test_x, test_y)
    )
    return 1 - squared_error / total_variation, slope, intercept
