def count_dates_by_year(csv_text, date_column):
    formats = (
        "%Y-%m-%d", "%Y/%m/%d",
        "%m/%d/%Y", "%m-%d-%Y",
        "%d/%m/%Y", "%d-%m-%Y",
        "%B %d, %Y", "%b %d, %Y",
        "%d %B %Y", "%d %b %Y",
    )

    reader = csv.DictReader(StringIO(csv_text))
    if reader.fieldnames is None or date_column not in reader.fieldnames:
        raise ValueError(f"Missing date column: {date_column}")

    counts = Counter()
    for row in reader:
        value = row[date_column]
        if value is None:
            raise ValueError("Missing date value")

        for fmt in formats:
            try:
                year = datetime.strptime(value.strip(), fmt).year
                break
            except ValueError:
                pass
        else:
            raise ValueError(f"Invalid date: {value!r}")

        counts[year] += 1

    return dict(counts)
