import xml.etree.ElementTree as ET


def xml_to_dict(s):
    if not s or not s.strip():
        raise ValueError("XML input is empty")

    def convert(element):
        result = {f"@{name}": value for name, value in element.attrib.items()}

        for child in element:
            value = convert(child)
            if child.tag not in result:
                result[child.tag] = value
            elif child.tag in repeated:
                result[child.tag].append(value)
            else:
                result[child.tag] = [result[child.tag], value]
                repeated.add(child.tag)

        text = "".join(
            [element.text or ""] + [child.tail or "" for child in element]
        ).strip()
        if text:
            if not result:
                return text
            result["#text"] = text

        return result or None

    root = ET.fromstring(s)
    repeated = set()
    return {root.tag: convert(root)}
```

