def dbscan_cluster_labels(points):
    def neighbors(i):
        return [
            j for j, point in enumerate(points)
            if sum((a - b) ** 2 for a, b in zip(points[i], point)) <= 9
        ]

    labels = [-1] * len(points)
    visited = [False] * len(points)
    cluster_id = 0

    for i in range(len(points)):
        if visited[i]:
            continue

        visited[i] = True
        seeds = neighbors(i)
        if len(seeds) < 2:
            continue

        labels[i] = cluster_id
        queued = set(seeds)
        pos = 0

        while pos < len(seeds):
            j = seeds[pos]
            pos += 1

            if not visited[j]:
                visited[j] = True
                nearby = neighbors(j)
                if len(nearby) >= 2:
                    for k in nearby:
                        if k not in queued:
                            seeds.append(k)
                            queued.add(k)

            if labels[j] == -1:
                labels[j] = cluster_id

        cluster_id += 1

    return labels
