from collections import deque

def dbscan_cluster_labels(points):
    """Cluster points with DBSCAN using Euclidean distance, eps=3, min_samples=2."""
    neighbors = [
        [
            j for j, other in enumerate(points)
            if sum((a - b) ** 2 for a, b in zip(point, other)) <= 9
        ]
        for point in points
    ]

    labels = [-1] * len(points)
    cluster_id = 0

    for i in range(len(points)):
        if labels[i] != -1 or len(neighbors[i]) < 2:
            continue

        labels[i] = cluster_id
        queue = deque([i])

        while queue:
            for j in neighbors[queue.popleft()]:
                if labels[j] == -1:
                    labels[j] = cluster_id
                    queue.append(j)

        cluster_id += 1

    return labels
