def dbscan_cluster_labels(points):
    """Cluster points with DBSCAN (Euclidean distance, eps=3, min_samples=2)."""
    n = len(points)
    neighbors = [[i] for i in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            distance_squared = sum(
                (a - b) ** 2 for a, b in zip(points[i], points[j])
            )
            if distance_squared <= 9:
                neighbors[i].append(j)
                neighbors[j].append(i)

    labels = [-1] * n
    visited = [False] * n
    cluster_id = 0

    for i in range(n):
        if visited[i]:
            continue
        visited[i] = True

        # With min_samples=2, a point is a core point if it has
        # at least one neighbor besides itself.
        if len(neighbors[i]) < 2:
            continue

        queue = [i]
        for point in queue:
            labels[point] = cluster_id
            for neighbor in neighbors[point]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        cluster_id += 1

    return labels
```

