def dbscan_cluster_labels(points):
    eps_squared = 3 ** 2
    labels = [None] * len(points)
    next_cluster = 0

    for start in range(len(points)):
        if labels[start] is not None:
            continue

        # With min_samples=2, any point with a neighbour is a core point.
        # Each connected component of nearby points is therefore a cluster.
        component = [start]
        labels[start] = -1  # Mark as visited; assign its final label below.

        for i in component:
            for j in range(len(points)):
                if labels[j] is None and sum(
                    (a - b) ** 2 for a, b in zip(points[i], points[j])
                ) <= eps_squared:
                    labels[j] = -1
                    component.append(j)

        if len(component) > 1:
            for i in component:
                labels[i] = next_cluster
            next_cluster += 1

    return labels
```

