def second_friday_sales_report(start_date, periods, categories, sales):
    if periods < 0:
        raise ValueError("periods must be nonnegative")
    if len(sales) != periods * len(categories):
        raise ValueError("sales must contain one value per date and category")

    start = date.fromisoformat(start_date)
    year, month = start.year, start.month
    report = []
    dates_found = 0

    while dates_found < periods:
        first = date(year, month, 1)
        second_friday = date(year, month, 1 + (4 - first.weekday()) % 7 + 7)

        if second_friday >= start:
            for category_index, category in enumerate(categories):
                value = sales[dates_found * len(categories) + category_index]
                report.append((second_friday.isoformat(), category, value))
            dates_found += 1

        if dates_found < periods:
            year, month = (year + 1, 1) if month == 12 else (year, month + 1)

    return report
