from datetime import date


def second_friday_sales_report(start_date, periods, categories, sales):
    start = date.fromisoformat(start_date)
    year, month = start.year, start.month

    def second_friday(year, month):
        first = date(year, month, 1)
        day = 1 + (4 - first.weekday()) % 7 + 7
        return date(year, month, day)

    def next_month(year, month):
        return (year + 1, 1) if month == 12 else (year, month + 1)

    report = []
    sales_index = 0

    for _ in range(periods):
        report_date = second_friday(year, month)
        while report_date < start:
            year, month = next_month(year, month)
            report_date = second_friday(year, month)

        for category in categories:
            report.append((report_date.isoformat(), category, sales[sales_index]))
            sales_index += 1

        year, month = next_month(year, month)

    return report
