import math

def threshold_and_standardize(data):
    if not data:
        return []

    thresholded = [[float(x) if x >= 0.5 else 0.0 for x in row] for row in data]
    result = [[0.0] * len(data[0]) for _ in data]

    for j in range(len(data[0])):
        column = [row[j] for row in thresholded]
        mean = sum(column) / len(column)
        std = math.sqrt(sum((x - mean) ** 2 for x in column) / len(column))

        if std != 0:
            for i, x in enumerate(column):
                result[i][j] = (x - mean) / std

    return result
