import math

def threshold_and_standardize(data):
    """Threshold values below 0.5, then standardize each column."""
    if not data:
        return []

    result = [[0.0] * len(data[0]) for _ in data]

    for col_index, column in enumerate(zip(*data)):
        values = [float(value) if value >= 0.5 else 0.0 for value in column]
        mean = math.fsum(values) / len(values)
        std = math.sqrt(
            math.fsum((value - mean) ** 2 for value in values) / len(values)
        )

        if std != 0:
            for row_index, value in enumerate(values):
                result[row_index][col_index] = (value - mean) / std

    return result
