from html.parser import HTMLParser


def html_table_records(html, table_id):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.depth = 0
            self.target_depth = None
            self.found = False
            self.rows = []
            self.row = None
            self.cell = None

        def handle_starttag(self, tag, attrs):
            if tag == "table":
                self.depth += 1
                if not self.found and dict(attrs).get("id") == table_id:
                    self.found = True
                    self.target_depth = self.depth
            elif self.depth == self.target_depth:
                if tag == "tr":
                    self.row = []
                elif tag in ("th", "td") and self.row is not None:
                    self.cell = []

        def handle_data(self, data):
            if self.cell is not None:
                self.cell.append(data)

        def handle_endtag(self, tag):
            if self.depth == self.target_depth:
                if tag in ("th", "td") and self.cell is not None:
                    self.row.append("".join(self.cell).strip())
                    self.cell = None
                elif tag == "tr" and self.row is not None:
                    self.rows.append(self.row)
                    self.row = None

            if tag == "table":
                if self.depth == self.target_depth:
                    self.target_depth = None
                self.depth -= 1

    parser = TableParser()
    parser.feed(html)

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")
    if not parser.rows:
        return []

    headers = parser.rows[0]
    return [dict(zip(headers, row)) for row in parser.rows[1:]]
