def extract_emails_from_html(
    html,
    pattern=r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,7}\b',
):
    class TextExtractor(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=False)
            self.parts = []

        def handle_data(self, data):
            self.parts.append(data)

        def handle_entityref(self, name):
            self.parts.append(f"&{name};")

        def handle_charref(self, name):
            self.parts.append(f"&#{name};")

    parser = TextExtractor()
    parser.feed(html)
    parser.close()

    text = html_module.unescape("".join(parser.parts))
    return re.findall(pattern, text)
```

Only text nodes are collected, so addresses found solely in tag attributes are excluded. Joining the text before matching also allows an address to span inline tags.

