import csv
import io


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    rows = []
    columns = None

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text, newline=""))
        if columns is None:
            columns = reader.fieldnames
        rows.extend(reader)

    def as_number(value):
        try:
            return int(value)
        except ValueError:
            return float(value)

    for column in columns:
        try:
            numbers = [as_number(row[column]) for row in rows]
        except (ValueError, TypeError):
            continue  # Keep the entire column as strings.

        for row, number in zip(rows, numbers):
            row[column] = number

    return rows
