import csv
import io


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    rows = []
    columns = None

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text))
        if reader.fieldnames is None:
            raise ValueError("CSV document has no header")

        if columns is None:
            columns = reader.fieldnames
        elif set(reader.fieldnames) != set(columns):
            raise ValueError("CSV documents must have the same columns")

        for row in reader:
            if None in row or any(row[column] is None for column in columns):
                raise ValueError("CSV row does not match its header")
            rows.append(row)

    def parse_number(value):
        try:
            return int(value)
        except ValueError:
            return float(value)

    for column in columns:
        try:
            values = [parse_number(row[column]) for row in rows]
        except ValueError:
            continue  # Keep every value in this column as a string.

        for row, value in zip(rows, values):
            row[column] = value

    return rows
