import math


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = {
        name: [mapping.get(value, value) for value in values]
        for name, values in data.items()
    }

    if not columns:
        return {}

    lengths = {len(values) for values in columns.values()}
    if len(lengths) != 1:
        raise ValueError("columns must have equal lengths")

    centered = {}
    sum_squares = {}
    for name, values in columns.items():
        mean = math.fsum(values) / len(values) if values else 0.0
        centered[name] = [value - mean for value in values]
        sum_squares[name] = math.fsum(x * x for x in centered[name])

    result = {name: {} for name in columns}
    names = list(columns)

    for i, a in enumerate(names):
        for b in names[i:]:
            denominator = math.sqrt(sum_squares[a] * sum_squares[b])
            if denominator == 0:
                correlation = math.nan
            elif a == b:
                correlation = 1.0
            else:
                numerator = math.fsum(
                    x * y for x, y in zip(centered[a], centered[b])
                )
                correlation = numerator / denominator

            result[a][b] = result[b][a] = correlation

    return result
