import math


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = {
        name: [float(mapping.get(value, value)) for value in values]
        for name, values in data.items()
    }

    result = {name: {} for name in columns}
    names = list(columns)

    for i, a in enumerate(names):
        x = columns[a]
        mean_x = math.fsum(x) / len(x) if x else 0.0
        dx = [value - mean_x for value in x]
        sum_xx = math.fsum(value * value for value in dx)

        for b in names[i:]:
            y = columns[b]
            mean_y = math.fsum(y) / len(y) if y else 0.0
            dy = [value - mean_y for value in y]
            sum_yy = math.fsum(value * value for value in dy)

            if len(x) < 2 or sum_xx == 0 or sum_yy == 0:
                correlation = math.nan
            else:
                correlation = math.fsum(u * v for u, v in zip(dx, dy))
                correlation /= math.sqrt(sum_xx * sum_yy)
                correlation = max(-1.0, min(1.0, correlation))

            result[a][b] = correlation
            result[b][a] = correlation

    return result
