import math


def score_grade_correlation(scores, grades):
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    try:
        numbers = [float(score) for score in scores]
    except (TypeError, ValueError) as exc:
        raise ValueError("every score must be a valid number") from exc

    if not all(math.isfinite(number) for number in numbers):
        raise ValueError("every score must be a finite number")

    if len(numbers) < 2:
        return None

    grade_codes = {grade: i for i, grade in enumerate(sorted(set(grades)))}
    encoded = [grade_codes[grade] for grade in grades]

    score_mean = math.fsum(numbers) / len(numbers)
    grade_mean = math.fsum(encoded) / len(encoded)
    score_diffs = [number - score_mean for number in numbers]
    grade_diffs = [grade - grade_mean for grade in encoded]

    numerator = math.fsum(x * y for x, y in zip(score_diffs, grade_diffs))
    denominator = math.sqrt(
        math.fsum(x * x for x in score_diffs)
        * math.fsum(y * y for y in grade_diffs)
    )
    return numerator / denominator if denominator else float("nan")
