from collections import Counter

def top_ten_words_from_csv(csv_text):
    rows = csv.reader(io.StringIO(csv_text))
    next(rows, None)  # Skip the header.

    counts = Counter()
    stopwords = {"a", "an", "the", "in", "on", "at", "and", "or"}

    for row in rows:
        if row:
            for match in re.finditer(r"\w{2,}", row[0]):
                word = match.group().casefold()
                if word not in stopwords:
                    counts[word] += 1

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:10]
