from itertools import combinations

def voronoi_neighbors(points):
    if len(points) < 3:
        raise ValueError("At least three points are required")

    edges = set()

    for i, j, k in combinations(range(len(points)), 3):
        xi, yi = points[i]
        bx, by = points[j][0] - xi, points[j][1] - yi
        cx, cy = points[k][0] - xi, points[k][1] - yi

        denominator = 2 * (bx * cy - by * cx)
        b2, c2 = bx * bx + by * by, cx * cx + cy * cy
        ux = (cy * b2 - by * c2) / denominator
        uy = (bx * c2 - cx * b2) / denominator
        radius2 = ux * ux + uy * uy

        # The triangle is Delaunay if its circumcircle contains no other point.
        if all(
            (points[m][0] - xi - ux) ** 2
            + (points[m][1] - yi - uy) ** 2 >= radius2
            for m in range(len(points))
            if m not in (i, j, k)
        ):
            edges.update(((i, j), (i, k), (j, k)))

    return sorted(edges)
```

Voronoi cells share an edge exactly when their sites are joined by a Delaunay edge. The assumed general position makes the circumcircle test unambiguous. This self-contained implementation takes \(O(n^4)\) time.

```python
from itertools import combinations

def voronoi_neighbors(points):
    """Return sorted pairs of points whose Voronoi cells share an edge."""
    if len(points) < 3:
        raise ValueError("at least three points are required")

    def orientation(a, b, c):
        return ((b[0] - a[0]) * (c[1] - a[1])
                - (b[1] - a[1]) * (c[0] - a[0]))

    def incircle(a, b, c, p):
        """Positive if p is inside the circle through counterclockwise a, b, c."""
        ax, ay = a[0] - p[0], a[1] - p[1]
        bx, by = b[0] - p[0], b[1] - p[1]
        cx, cy = c[0] - p[0], c[1] - p[1]
        return (
            (ax * ax + ay * ay) * (bx * cy - by * cx)
            - (bx * bx + by * by) * (ax * cy - ay * cx)
            + (cx * cx + cy * cy) * (ax * by - ay * bx)
        )

    edges = set()
    for i, j, k in combinations(range(len(points)), 3):
        a, b, c = points[i], points[j], points[k]
        direction = orientation(a, b, c)

        # An empty circumcircle makes this a Delaunay triangle.
        if all(
            incircle(a, b, c, points[p]) * direction < 0
            for p in range(len(points))
            if p not in (i, j, k)
        ):
            edges.update(((i, j), (i, k), (j, k)))

    return sorted(edges)
```

Voronoi cells share an edge exactly when their sites are connected by a Delaunay edge. Under the stated general-position assumption, the empty-circumcircle test finds those edges. This implementation takes \(O(n^4)\) time.

