def cluster_centroids(points, k):
    """Return k-means centroids, sorted by x then y."""
    if not 1 <= k <= len(points):
        raise ValueError("k must be between 1 and the number of points")

    points = [tuple(map(float, point)) for point in points]

    def distance_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic farthest-first initialization.
    centroids = [min(points)]
    while len(centroids) < k:
        centroids.append(
            max(points, key=lambda p: min(distance_sq(p, c) for c in centroids))
        )

    for _ in range(300):
        clusters = [[] for _ in range(k)]
        for point in points:
            closest = min(range(k), key=lambda i: distance_sq(point, centroids[i]))
            clusters[closest].append(point)

        updated = [
            (sum(p[0] for p in cluster) / len(cluster),
             sum(p[1] for p in cluster) / len(cluster))
            if cluster else centroids[i]
            for i, cluster in enumerate(clusters)
        ]
        if updated == centroids:
            break
        centroids = updated

    return sorted(centroids)
