def cluster_centroids(points, k):
    """Return k 2D k-means centroids in ascending order."""
    if not 1 <= k <= len(points):
        raise ValueError("k must be between 1 and the number of points")

    points = [tuple(map(float, point)) for point in points]

    def distance_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Choose initial centroids deterministically, spreading them apart.
    chosen = [min(range(len(points)), key=lambda i: points[i])]
    while len(chosen) < k:
        remaining = (i for i in range(len(points)) if i not in chosen)
        chosen.append(min(
            remaining,
            key=lambda i: (
                -min(distance_sq(points[i], points[j]) for j in chosen),
                points[i],
            ),
        ))

    centroids = [points[i] for i in chosen]

    for _ in range(300):
        clusters = [[] for _ in range(k)]
        for point in points:
            nearest = min(range(k), key=lambda i: distance_sq(point, centroids[i]))
            clusters[nearest].append(point)

        updated = [
            (sum(x for x, _ in cluster) / len(cluster),
             sum(y for _, y in cluster) / len(cluster))
            if cluster else centroids[i]
            for i, cluster in enumerate(clusters)
        ]

        if updated == centroids:
            break
        centroids = updated

    return sorted(centroids)
