    # Choose deterministic starting centroids: the smallest point, then
    # points farthest from the centroids already chosen.
    centroids = [points[0]]
    chosen = {0}
    while len(centroids) < k:
        index = max(
            (i for i in range(len(points)) if i not in chosen),
            key=lambda i: (
                min(distance_sq(points[i], c) for c in centroids),
                -i,
            ),
        )
        chosen.add(index)
        centroids.append(points[index])

    previous_assignments = None
    while True:
        assignments = [
            min(range(k), key=lambda j: distance_sq(point, centroids[j]))
            for point in points
        ]
        if assignments == previous_assignments:
            return sorted(centroids)

        groups = [[] for _ in range(k)]
        for point, cluster in zip(points, assignments):
            groups[cluster].append(point)

        centroids = [
            (sum(x for x, _ in group) / len(group),
             sum(y for _, y in group) / len(group))
            if group else centroids[i]
            for i, group in enumerate(groups)
        ]
        previous_assignments = assignments
