from math import fsum


def cluster_centroids(points, k):
    """Return k deterministic k-means centroids, sorted by (x, y)."""
    if not 1 <= k <= len(points):
        raise ValueError("k must be between 1 and the number of points")

    pts = sorted((float(x), float(y)) for x, y in points)

    def distance_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Choose initial centroids by repeatedly taking the farthest point.
    chosen = {0}
    centers = [pts[0]]
    while len(centers) < k:
        i = max(
            (i for i in range(len(pts)) if i not in chosen),
            key=lambda i: (min(distance_sq(pts[i], c) for c in centers), -i),
        )
        chosen.add(i)
        centers.append(pts[i])

    previous_labels = None
    while True:
        labels = [
            min(range(k), key=lambda j: distance_sq(p, centers[j]))
            for p in pts
        ]
        counts = [labels.count(j) for j in range(k)]

        # Give each empty cluster a point from a cluster with spare points.
        for empty in (j for j in range(k) if counts[j] == 0):
            i = max(
                (i for i, j in enumerate(labels) if counts[j] > 1),
                key=lambda i: distance_sq(pts[i], centers[labels[i]]),
            )
            counts[labels[i]] -= 1
            labels[i] = empty
            counts[empty] += 1

        if labels == previous_labels:
            return sorted(centers)

        centers = [
            (
                fsum(p[0] for p, label in zip(pts, labels) if label == j) / counts[j],
                fsum(p[1] for p, label in zip(pts, labels) if label == j) / counts[j],
            )
            for j in range(k)
        ]
        previous_labels = labels
