    for _ in range(1, k):
        centroids.append(
            max(
                points,
                key=lambda p: min(distance_sq(p, c) for c in centroids),
            )
        )

    previous_assignments = None
    while True:
        assignments = [
            min(range(k), key=lambda i: distance_sq(point, centroids[i]))
            for point in points
        ]
        if assignments == previous_assignments:
            break
        previous_assignments = assignments

        clusters = [[] for _ in range(k)]
        for point, cluster_index in zip(points, assignments):
            clusters[cluster_index].append(point)

        centroids = [
            (
                fsum(x for x, _ in cluster) / len(cluster),
                fsum(y for _, y in cluster) / len(cluster),
            ) if cluster else centroids[i]
            for i, cluster in enumerate(clusters)
        ]

    return sorted(centroids)
