import calendar
import re
from datetime import date

def forecast_schedule(start_date, freq, sales):
    if not isinstance(start_date, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date):
        raise ValueError("Invalid start date")

    try:
        start = date.fromisoformat(start_date)
    except ValueError as exc:
        raise ValueError("Invalid start date") from exc

    weekdays = {"MON": 0, "TUE": 1, "WED": 2, "THU": 3,
                "FRI": 4, "SAT": 5, "SUN": 6}

    if freq not in ("month-end", "quarter-end"):
        match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq)
        if not match:
            raise ValueError("Invalid frequency")
        week, weekday = int(match.group(1)), weekdays[match.group(2)]

    result = []
    year, month = start.year, start.month

    for sale in sales:
        while True:
            last_day = calendar.monthrange(year, month)[1]

            if freq == "month-end":
                scheduled = date(year, month, last_day)
            elif freq == "quarter-end":
                scheduled = date(year, month, last_day) if month in (3, 6, 9, 12) else None
            else:
                first_weekday = date(year, month, 1).weekday()
                day = 1 + (weekday - first_weekday) % 7 + (week - 1) * 7
                scheduled = date(year, month, day) if day <= last_day else None

            if scheduled is not None and scheduled >= start:
                result.append((scheduled.isoformat(), sale))
                month += 1
                if month == 13:
                    year, month = year + 1, 1
                break

            month += 1
            if month == 13:
                year, month = year + 1, 1

    return result
