import calendar
import re
from datetime import date


def forecast_schedule(start_date, freq, sales):
    """Pair sales figures with consecutive dates matching freq."""
    if not isinstance(start_date, str) or not re.fullmatch(
        r"\d{4}-\d{2}-\d{2}", start_date
    ):
        raise ValueError("start_date must be a valid YYYY-MM-DD date")

    try:
        start = date.fromisoformat(start_date)
    except ValueError as exc:
        raise ValueError("start_date must be a valid YYYY-MM-DD date") from exc

    if freq == "month-end":
        step = 1
        nth_weekday = None
    elif freq == "quarter-end":
        step = 3
        nth_weekday = None
    else:
        match = re.fullmatch(
            r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq
        ) if isinstance(freq, str) else None
        if not match:
            raise ValueError("invalid frequency")
        step = 1
        nth_weekday = (
            int(match.group(1)),
            ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN").index(
                match.group(2)
            ),
        )

    month_index = start.year * 12 + start.month - 1
    if freq == "quarter-end":
        month_index += (2 - month_index % 3) % 3

    def scheduled_date(index):
        year, month_zero_based = divmod(index, 12)
        month = month_zero_based + 1

        if nth_weekday is None:
            day = calendar.monthrange(year, month)[1]
        else:
            week, weekday = nth_weekday
            first_weekday = date(year, month, 1).weekday()
            day = 1 + (weekday - first_weekday) % 7 + 7 * (week - 1)

        return date(year, month, day)

    while scheduled_date(month_index) < start:
        month_index += step

    result = []
    for sale in sales:
        result.append((scheduled_date(month_index).isoformat(), sale))
        month_index += step
    return result
