def forecast_schedule(start_date, freq, sales):
    """Pair sales figures with consecutive dates matching freq."""
    if not isinstance(start_date, str) or not re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2}", start_date
    ):
        raise ValueError("start_date must be a valid YYYY-MM-DD date")

    try:
        start = date.fromisoformat(start_date)
    except ValueError as exc:
        raise ValueError("start_date must be a valid YYYY-MM-DD date") from exc

    weekdays = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN")
    if freq in ("month-end", "quarter-end"):
        match = None
    else:
        match = re.fullmatch(
            r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq
        ) if isinstance(freq, str) else None
        if match is None:
            raise ValueError("invalid frequency")

    def scheduled_date(year, month):
        if freq == "month-end" or freq == "quarter-end":
            day = calendar.monthrange(year, month)[1]
        else:
            week = int(match.group(1))
            weekday = weekdays.index(match.group(2))
            first_weekday = date(year, month, 1).weekday()
            day = 1 + (weekday - first_weekday) % 7 + 7 * (week - 1)
        return date(year, month, day)

    # Represent months as a zero-based index to make advancing easy.
    month_index = (start.year - 1) * 12 + start.month - 1
    step = 3 if freq == "quarter-end" else 1
    if freq == "quarter-end":
        month_index += 2 - month_index % 3  # March, June, September, or December

    def date_at(index):
        year, zero_based_month = divmod(index, 12)
        return scheduled_date(year + 1, zero_based_month + 1)

    if date_at(month_index) < start:
        month_index += step

    result = []
    for sale in sales:
        result.append((date_at(month_index).isoformat(), sale))
