        raise ValueError("Invalid start date; expected YYYY-MM-DD") from exc

    weekdays = {"MON": 0, "TUE": 1, "WED": 2, "THU": 3,
                "FRI": 4, "SAT": 5, "SUN": 6}
    match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq)
    if freq not in ("month-end", "quarter-end") and not match:
        raise ValueError("Invalid frequency")

    result = []
    year, month = start.year, start.month

    for sale in sales:
        while True:
            if freq == "quarter-end" and month not in (3, 6, 9, 12):
                candidate = None
            elif match:
                week = int(match.group(1))
                weekday = weekdays[match.group(2)]
                first_weekday = date(year, month, 1).weekday()
                day = 1 + (weekday - first_weekday) % 7 + 7 * (week - 1)
                candidate = date(year, month, day)
            else:
                candidate = date(year, month, calendar.monthrange(year, month)[1])

            if candidate is not None and candidate >= start:
                result.append((candidate.isoformat(), sale))
                break

            year, month = (year + 1, 1) if month == 12 else (year, month + 1)

        if len(result) < len(sales):
            year, month = (year + 1, 1) if month == 12 else (year, month + 1)

    return result
