import csv
from collections import Counter
from io import StringIO


def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(StringIO(csv_text))
    required = {"Customer", "Category", "Sales"}
    if not reader.fieldnames or not required.issubset(reader.fieldnames):
        raise ValueError("CSV must include Customer, Category, and Sales columns")

    seen_customers = set()
    category_counts = Counter()
    total_sales = 0

    for row in reader:
        customer = row["Customer"]
        if customer in seen_customers:
            continue

        sales = row["Sales"]
        try:
            amount = int(sales)
        except ValueError:
            amount = float(sales)

        seen_customers.add(customer)
        total_sales += amount
        category_counts[row["Category"]] += 1

    most_popular = (
        min(category_counts, key=lambda category: (-category_counts[category], category))
        if category_counts else None
    )
    return {"Total Sales": total_sales, "Most Popular Category": most_popular}
