        raise ValueError("records must not be empty")

    scores_by_country = defaultdict(list)
    seen_names = set()

    for record in records:
        if not isinstance(record, dict) or not {"Name", "Country", "Score"} <= record.keys():
            raise ValueError("Each record must have Name, Country, and Score")

        if record["Name"] in seen_names:
            continue

        seen_names.add(record["Name"])
        scores_by_country[record["Country"]].append(float(record["Score"]))

    def quantile(sorted_scores, fraction):
        position = fraction * (len(sorted_scores) - 1)
        lower = int(position)
        upper = min(lower + 1, len(sorted_scores) - 1)
        return sorted_scores[lower] + (position - lower) * (
            sorted_scores[upper] - sorted_scores[lower]
        )

    return {
        country: [quantile(sorted(scores), q) for q in (0, 0.25, 0.5, 0.75, 1)]
        for country, scores in scores_by_country.items()
    }
