from numbers import Number


def column_covariance(columns):
    if not columns:
        raise ValueError("The table has no columns")

    names = list(columns)
    n = len(columns[names[0]])
    if n < 2:
        raise ValueError("The table must have at least two rows")

    for name in names:
        values = columns[name]
        if len(values) != n:
            raise ValueError("Columns must have equal lengths")
        if any(not isinstance(value, Number) for value in values):
            raise TypeError(f"Column {name!r} contains a non-numeric value")

    # Subtract the first row to keep intermediate values smaller.
    offsets = {
        name: [value - columns[name][0] for value in columns[name]]
        for name in names
    }
    totals = {name: sum(offsets[name]) for name in names}
    result = {name: {} for name in names}

    for i, a in enumerate(names):
        for b in names[i:]:
            covariance = (
                sum(x * y for x, y in zip(offsets[a], offsets[b]))
                - totals[a] * totals[b] / n
            ) / (n - 1)
            result[a][b] = result[b][a] = covariance

    return result
