def cluster_point_indices(points, n_clusters):
    if not 1 <= n_clusters <= len(points):
        raise ValueError("n_clusters must be between 1 and the number of points")

    def squared_distance(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Choose initial centers deterministically: the first point, then the
    # point farthest from its nearest existing center.
    centers = [list(points[0])]
    chosen = {0}
    while len(centers) < n_clusters:
        index = max(
            (i for i in range(len(points)) if i not in chosen),
            key=lambda i: min(squared_distance(points[i], c) for c in centers),
        )
        chosen.add(index)
        centers.append(list(points[index]))

    labels = [-1] * len(points)
    for _ in range(300):
        new_labels = [
            min(range(n_clusters), key=lambda c: squared_distance(point, centers[c]))
            for point in points
        ]
        clusters = [[] for _ in range(n_clusters)]
        for i, label in enumerate(new_labels):
            clusters[label].append(i)

        # Keep every cluster nonempty, even when points are identical.
        for empty in (c for c in range(n_clusters) if not clusters[c]):
            donor_point = max(
                (i for c in range(n_clusters) if len(clusters[c]) > 1
                 for i in clusters[c]),
                key=lambda i: (squared_distance(points[i], centers[new_labels[i]]), -i),
            )
            clusters[new_labels[donor_point]].remove(donor_point)
            clusters[empty].append(donor_point)
            new_labels[donor_point] = empty

        centers = [
            [sum(points[i][d] for i in cluster) / len(cluster)
             for d in range(len(points[0]))]
            for cluster in clusters
        ]
        if new_labels == labels:
            break
        labels = new_labels

    return sorted((sorted(cluster) for cluster in clusters), key=lambda c: c[0])
