def cluster_point_indices(points, n_clusters):
    """Cluster points with a deterministic k-means implementation."""
    n = len(points)
    if not 1 <= n_clusters <= n:
        raise ValueError("n_clusters must be between 1 and len(points)")
    if any(len(point) != len(points[0]) for point in points):
        raise ValueError("all points must have the same dimension")

    def distance_squared(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Choose the first center, then repeatedly choose the farthest point.
    seeds = [0]
    while len(seeds) < n_clusters:
        seeds.append(max(
            (i for i in range(n) if i not in seeds),
            key=lambda i: (
                min(distance_squared(points[i], points[s]) for s in seeds),
                -i,
            ),
        ))

    centers = [list(points[i]) for i in seeds]
    labels = [-1] * n
    for cluster, index in enumerate(seeds):
        labels[index] = cluster

    while True:
        new_labels = [
            min(
                range(n_clusters),
                key=lambda j: (
                    distance_squared(point, centers[j]),
                    j != labels[i],  # Keep the current cluster on a tie.
                    j,
                ),
            )
            for i, point in enumerate(points)
        ]

        groups = [[i for i, label in enumerate(new_labels) if label == j]
                  for j in range(n_clusters)]

        # Give any empty cluster a point from a cluster with multiple points.
        for empty in (j for j in range(n_clusters) if not groups[j]):
            i = max(
                (i for i in range(n) if len(groups[new_labels[i]]) > 1),
                key=lambda i: (
                    distance_squared(points[i], centers[new_labels[i]]),
                    -i,
                ),
            )
            groups[new_labels[i]].remove(i)
            groups[empty].append(i)
            new_labels[i] = empty

        if new_labels == labels:
            break

        labels = new_labels
        centers = [
            [sum(points[i][d] for i in group) / len(group)
             for d in range(len(points[0]))]
            for group in groups
        ]

    return sorted((sorted(group) for group in groups), key=lambda group: group[0])
