    """Cluster points with deterministic k-means; return sorted index groups."""
    n = len(points)
    if not 1 <= n_clusters <= n:
        raise ValueError("n_clusters must be between 1 and len(points)")

    def distance_squared(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Initialize centers with the first point, then the points farthest
    # from their nearest existing center.
    chosen = {0}
    centers = [points[0]]
    while len(centers) < n_clusters:
        index = max(
            (i for i in range(n) if i not in chosen),
            key=lambda i: (
                min(distance_squared(points[i], c) for c in centers),
                -i,
            ),
        )
        chosen.add(index)
        centers.append(points[index])

    labels = [-1] * n
    while True:
        new_labels = []
        for i, point in enumerate(points):
            new_labels.append(min(
                range(n_clusters),
                key=lambda c: (
                    distance_squared(point, centers[c]),
                    c != labels[i],  # Keep the previous cluster on a tie.
                    c,
                ),
            ))

        counts = [new_labels.count(c) for c in range(n_clusters)]
        for empty in range(n_clusters):
            if counts[empty] == 0:
                index = max(
                    (i for i in range(n) if counts[new_labels[i]] > 1),
                    key=lambda i: (
                        distance_squared(points[i], centers[new_labels[i]]),
                        -i,
