import csv
import io
import math


def sort_csv_rows(csv_text, sort_key):
    reader = csv.DictReader(io.StringIO(csv_text, newline=""))
    if reader.fieldnames is None or sort_key not in reader.fieldnames:
        raise ValueError(f"Column does not exist: {sort_key}")

    rows = list(reader)

    for column in reader.fieldnames:
        converted = []
        for row in rows:
            value = row[column]
            try:
                number = int(value)
            except (ValueError, TypeError):
                try:
                    number = float(value)
                except (ValueError, TypeError):
                    break
                if not math.isfinite(number):
                    break
            converted.append(number)
        else:
            for row, number in zip(rows, converted):
                row[column] = number

    return sorted(rows, key=lambda row: row[sort_key])
```

Python’s sort is stable, so rows with equal keys retain their original order.

