```python
def kmeans_clusters(xs, ys, n_clusters):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if not isinstance(n_clusters, int) or not 1 <= n_clusters <= n:
        raise ValueError("n_clusters must be between 1 and the number of points")

    points = list(zip(xs, ys))

    def distance_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Choose initial centers deterministically, spreading them apart.
    seeds = [0]
    while len(seeds) < n_clusters:
        seeds.append(max(
            (i for i in range(n) if i not in seeds),
            key=lambda i: (
                min(distance_sq(points[i], points[s]) for s in seeds),
                -i,
            ),
        ))
    centers = [points[i] for i in seeds]

    previous_labels = None
    for _ in range(300):
        labels = [
            min(range(n_clusters), key=lambda j: distance_sq(point, centers[j]))
            for point in points
        ]
        clusters = [[i for i, label in enumerate(labels) if label == j]
                    for j in range(n_clusters)]

        # Give each empty cluster a point from a cluster with multiple points.
        for empty in (j for j in range(n_clusters) if not clusters[j]):
            donor_point = max(
                (i for i in range(n) if len(clusters[labels[i]]) > 1),
                key=lambda i: (distance_sq(points[i], centers[labels[i]]), -i),
            )
            clusters[labels[donor_point]].remove(donor_point)
            labels[donor_point] = empty
            clusters[empty].append(donor_point)

        if labels == previous_labels:
            break
        previous_labels = labels

        centers = [
            (
                sum(points[i][0] for i in cluster) / len(cluster),
                sum(points[i][1] for i in cluster) / len(cluster),
            )
            for cluster in clusters
        ]

    return sorted((sorted(cluster) for cluster in clusters), key=lambda c: c[0])
```

