```python
def kmeans_clusters(xs, ys, n_clusters):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    points = list(zip(xs, ys))
    if not 1 <= n_clusters <= len(points):
        raise ValueError("n_clusters must be between 1 and the number of points")

    def distance_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Choose initial centers deterministically, starting at point 0 and
    # repeatedly choosing the point farthest from any existing center.
    chosen = [0]
    while len(chosen) < n_clusters:
        next_index = max(
            (i for i in range(len(points)) if i not in chosen),
            key=lambda i: (
                min(distance_sq(points[i], points[j]) for j in chosen),
                -i,
            ),
        )
        chosen.append(next_index)

    centers = [points[i] for i in chosen]
    labels = [None] * len(points)

    for _ in range(300):
        new_labels = []
        for point, previous in zip(points, labels):
            distances = [distance_sq(point, center) for center in centers]
            best = min(distances)
            # Keep the previous label when centers are tied.
            if previous is not None and distances[previous] == best:
                new_labels.append(previous)
            else:
                new_labels.append(distances.index(best))

        groups = [[] for _ in range(n_clusters)]
        for i, label in enumerate(new_labels):
            groups[label].append(i)

        # Give any empty cluster a point from a cluster with spare points.
        for empty in range(n_clusters):
            if groups[empty]:
                continue
            donor_point = max(
                (i for group in groups if len(group) > 1 for i in group),
                key=lambda i: (distance_sq(points[i], centers[new_labels[i]]), -i),
            )
            groups[new_labels[donor_point]].remove(donor_point)
            groups[empty].append(donor_point)
            new_labels[donor_point] = empty

        if new_labels == labels:
            break

        labels = new_labels
        centers = [
            (
                sum(xs[i] for i in group) / len(group),
                sum(ys[i] for i in group) / len(group),
            )
            for group in groups
        ]

    return sorted((sorted(group) for group in groups), key=lambda group: group[0])
