import json
import math


def numeric_correlation_from_json(json_text):
    """Return Pearson correlations for columns containing only numeric values."""
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data must be a non-empty JSON object")

    if any(not isinstance(values, list) for values in data.values()):
        raise ValueError("Every column must be a list")

    lengths = {len(values) for values in data.values()}
    if len(lengths) != 1 or 0 in lengths:
        raise ValueError("Columns must have the same non-zero length")

    columns = {
        name: values
        for name, values in data.items()
        if all(
            isinstance(value, (int, float)) and not isinstance(value, bool)
            for value in values
        )
    }

    centered = {}
    squared_sums = {}
    for name, values in columns.items():
        mean = math.fsum(values) / len(values)
        centered[name] = [value - mean for value in values]
        squared_sums[name] = math.fsum(x * x for x in centered[name])

    result = {name: {} for name in columns}
    for name_a in columns:
        for name_b in columns:
            denominator = math.sqrt(squared_sums[name_a]) * math.sqrt(
                squared_sums[name_b]
            )
            result[name_a][name_b] = (
                math.fsum(a * b for a, b in zip(centered[name_a], centered[name_b]))
                / denominator
                if denominator
                else float("nan")
            )

    return result
```

A constant column has undefined Pearson correlation, represented here by `nan`.

