import json
import math


def numeric_correlation_from_json(json_text):
    def reject_nonstandard_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        data = json.loads(
            json_text, parse_constant=reject_nonstandard_constant
        )
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("JSON must contain a non-empty object")

    if any(not isinstance(values, list) for values in data.values()):
        raise ValueError("Each column must be a list")
    if len({len(values) for values in data.values()}) != 1:
        raise ValueError("Columns must have equal lengths")

    numeric = {
        name: values
        for name, values in data.items()
        if all(
            type(value) in (int, float) and math.isfinite(value)
            for value in values
        )
    }

    def correlation(xs, ys):
        if len(xs) < 2:
            return math.nan

        x_mean = math.fsum(xs) / len(xs)
        y_mean = math.fsum(ys) / len(ys)
        x_centered = [x - x_mean for x in xs]
        y_centered = [y - y_mean for y in ys]
        x_norm = math.hypot(*x_centered)
        y_norm = math.hypot(*y_centered)

        if x_norm == 0 or y_norm == 0:
            return math.nan  # Pearson correlation is undefined.

        return math.fsum(
            (x / x_norm) * (y / y_norm)
            for x, y in zip(x_centered, y_centered)
        )

    return {
        x_name: {
            y_name: correlation(xs, ys)
            for y_name, ys in numeric.items()
        }
        for x_name, xs in numeric.items()
    }
```

Columns containing non-numeric values, including booleans, are ignored. Constant columns have undefined correlations, represented by `math.nan`.

