from collections import Counter


def classification_summary(y_true, y_pred):
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")

    labels = dict.fromkeys([*y_true, *y_pred])
    true_counts = Counter(y_true)
    pred_counts = Counter(y_pred)
    correct_counts = Counter(
        true for true, pred in zip(y_true, y_pred) if true == pred
    )
    total = len(y_true)

    report = {}
    for label in labels:
        tp = correct_counts[label]
        support = true_counts[label]
        precision = tp / pred_counts[label] if pred_counts[label] else 0.0
        recall = tp / support if support else 0.0
        f1 = (
            2 * precision * recall / (precision + recall)
            if precision + recall else 0.0
        )
        report[label] = (precision, recall, f1, support)

    report["accuracy"] = sum(correct_counts.values()) / total if total else 0.0
    report["macro avg"] = (
        *(
            sum(report[label][i] for label in labels) / len(labels)
            if labels else 0.0
            for i in range(3)
        ),
        total,
    )
    report["weighted avg"] = (
        *(
            sum(report[label][i] * (true_counts[label] / total)
                for label in labels)
            if total else 0.0
            for i in range(3)
        ),
        total,
    )
    return report
