from collections import Counter
from math import log, sqrt


def tfidf_matrix(documents):
    def words_in(text):
        word = []
        for char in text:
            if char.isalpha() or char.isdigit():
                word.append(char)
            elif word:
                yield "".join(word).lower()
                word = []
        if word:
            yield "".join(word).lower()

    counts = [Counter(words_in(doc)) for doc in documents]
    words = sorted(set().union(*(count.keys() for count in counts)))
    n = len(documents)

    df = {word: sum(word in count for count in counts) for word in words}
    idf = {word: log((1 + n) / (1 + df[word])) + 1 for word in words}

    rows = []
    for count in counts:
        scores = [count[word] * idf[word] for word in words]
        length = sqrt(sum(score * score for score in scores))
        rows.append([score / length for score in scores] if length else scores)

    return words, rows
