def complete_row_histogram(data, bins):
    if not isinstance(bins, int) or isinstance(bins, bool) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    cleaned = {name: [] for name in data}
    values = []

    for row in zip(*data.values()):
        if any(value is None for value in row):
            continue

        for name, value in zip(data, row):
            number = float(value)
            cleaned[name].append(number)
            values.append(number)

    if not values or min(values) == max(values):
        return cleaned, None

    minimum, maximum = min(values), max(values)
    counts = [0] * bins

    for value in values:
        index = min(int((value - minimum) / (maximum - minimum) * bins), bins - 1)
        counts[index] += 1

    return cleaned, counts
```

