import csv
import io
import math


def correlation_matrix_from_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    names = next(reader)
    columns = {name: [] for name in names}

    for row in reader:
        if len(row) != len(names):
            raise ValueError("CSV row has the wrong number of columns")
        for name, value in zip(names, row):
            columns[name].append(float(value))

    means = {
        name: math.fsum(values) / len(values) if values else float("nan")
        for name, values in columns.items()
    }
    centered = {
        name: [value - means[name] for value in values]
        for name, values in columns.items()
    }
    sums_of_squares = {
        name: math.fsum(value * value for value in values)
        for name, values in centered.items()
    }

    result = {name: {} for name in names}
    for i, a in enumerate(names):
        for b in names[i:]:
            denominator = math.sqrt(sums_of_squares[a] * sums_of_squares[b])
            correlation = (
                math.fsum(x * y for x, y in zip(centered[a], centered[b]))
                / denominator
                if denominator
                else float("nan")
            )
            result[a][b] = result[b][a] = correlation

    return result
```

Correlations involving a constant column—or no data rows—are undefined, so this returns `nan` for those entries.

