from io import StringIO


def correlation_matrix_from_csv(csv_text):
    reader = csv.reader(StringIO(csv_text))
    headers = next(reader, None)
    if not headers or len(set(headers)) != len(headers):
        raise ValueError("CSV must have a header with unique column names")

    rows = []
    for row in reader:
        if len(row) != len(headers):
            raise ValueError("Each row must have the same number of fields as the header")
        values = [float(value) for value in row]
        if not all(math.isfinite(value) for value in values):
            raise ValueError("Values must be finite")
        rows.append(values)

    if len(rows) < 2:
        raise ValueError("At least two data rows are required")

    columns = list(zip(*rows))
    means = [math.fsum(column) / len(column) for column in columns]
    centered = [
        [value - mean for value in column]
        for column, mean in zip(columns, means)
    ]
    sums_of_squares = [
        math.fsum(value * value for value in column)
        for column in centered
    ]
    if any(total == 0 for total in sums_of_squares):
        raise ValueError("Correlation is undefined for a constant column")

    result = {name: {} for name in headers}
    for i, a in enumerate(headers):
        for j, b in enumerate(headers):
            result[a][b] = (
                1.0 if i == j else
                math.fsum(x * y for x, y in zip(centered[i], centered[j]))
                / math.sqrt(sums_of_squares[i] * sums_of_squares[j])
            )
    return result
