def document_term_matrix(texts, stop_words):
    stop = {word.lower() for word in stop_words}
    documents = []

    for text in texts:
        words = (
            "".join(group)
            for is_word, group in groupby(
                text.lower(), key=lambda char: char.isalpha() or char.isdigit()
            )
            if is_word
        )
        documents.append(Counter(word for word in words if word not in stop))

    terms = sorted(set().union(*(counts.keys() for counts in documents)))
    counts = [[document[term] for term in terms] for document in documents]
    return terms, counts
