import math

def last_column_skewness(rows):
    if not rows or not rows[0]:
        raise ValueError("table must have at least one row and one column")

    values = [row[-1] for row in rows if row[-1] is not None]
    if not values:
        return float("nan")

    mean = math.fsum(values) / len(values)
    deviations = [value - mean for value in values]
    m2 = math.fsum(d**2 for d in deviations) / len(values)

    if m2 == 0:
        return float("nan")

    m3 = math.fsum(d**3 for d in deviations) / len(values)
    return m3 / m2**1.5
```

This uses the biased Fisher–Pearson coefficient, \(m_3/m_2^{3/2}\). It returns `nan` when skewness is undefined because there are no non-missing values or no variation.

