from numbers import Real

def normalize_columns(data):
    if not data:
        raise ValueError("data must contain at least one column")

    result = {}
    for name, values in data.items():
        if any(not isinstance(value, Real) for value in values):
            raise ValueError(f"column {name!r} contains non-numeric values")

        if not values:
            result[name] = []
            continue

        low, high = min(values), max(values)
        result[name] = (
            [0.0] * len(values)
            if low == high
            else [float((value - low) / (high - low)) for value in values]
        )

    return result
