import numpy as np

def fit_joined_regression(feature_rows, target_rows, features, target):
    targets_by_id = {row["id"]: row for row in target_rows}
    joined = [
        (row, targets_by_id[row["id"]])
        for row in feature_rows
        if row["id"] in targets_by_id
    ]
    if not joined:
        raise ValueError("No ids are present in both inputs")

    # The first column of ones fits the intercept.
    X = np.array(
        [[1.0, *(feature_row[name] for name in features)]
         for feature_row, _ in joined],
        dtype=float,
    )
    y = np.array(
        [target_row[target] for _, target_row in joined],
        dtype=float,
    )

    fitted, _, _, _ = np.linalg.lstsq(X, y, rcond=None)
    return {
        "coefficients": fitted[1:].tolist(),
        "intercept": float(fitted[0]),
        "residuals": (y - X @ fitted).tolist(),
    }
```

The join follows `feature_rows` order. Results may differ from the example by tiny floating-point rounding amounts.

