from collections import defaultdict

def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = defaultdict(list)
    for fruit, day, sales in records:
        sales_by_fruit[fruit].append(sales)

    def quartile(sorted_values, proportion):
        position = (len(sorted_values) - 1) * proportion
        lower = int(position)
        fraction = position - lower
        if fraction == 0:
            return float(sorted_values[lower])
        return float(
            sorted_values[lower]
            + fraction * (sorted_values[lower + 1] - sorted_values[lower])
        )

    return {
        fruit: tuple(
            quartile(values, proportion)
            for proportion in (0, 0.25, 0.5, 0.75, 1)
        )
        for fruit, sales in sales_by_fruit.items()
        for values in (sorted(sales),)
    }
