        if fraction == 0:
            return float(values[lower])
        return float(values[lower] + fraction * (values[lower + 1] - values[lower]))

    result = {}
    for fruit, sales in sales_by_fruit.items():
        values = sorted(sales)
        result[fruit] = tuple(
            percentile(values, p) for p in (0, 0.25, 0.5, 0.75, 1)
        )

    return result
