        return float(
            sorted_values[lower]
            + fraction * (sorted_values[upper] - sorted_values[lower])
        )

    return {
        fruit: tuple(
            percentile(values, p) for p in (0, 0.25, 0.5, 0.75, 1)
        )
        for fruit, values in (
            (fruit, sorted(sales)) for fruit, sales in sales_by_fruit.items()
        )
    }
