    for name in features:
        if name not in table:
            raise ValueError(f"Feature not found: {name}")

        values = [mapping.get(value, value) for value in table[name]]
        if not values:
            raise ValueError(f"Feature has no values: {name}")

        counts = Counter(values)
        highest_count = max(counts.values())

        result[name] = {
            "mean": fmean(values),
            "median": float(median(values)),
            "mode": min(value for value, count in counts.items()
                        if count == highest_count),
            "variance": float(pvariance(values)),
        }

    return result
