            if tag == "a":
                href = next((value for name, value in attrs if name == "href"), None)
                self.links.append([[], href])
                self.open_links.append(len(self.links) - 1)

        def handle_data(self, data):
            for index in self.open_links:
                self.links[index][0].append(data)

        def handle_endtag(self, tag):
            if tag == "a" and self.open_links:
                self.open_links.pop()

    parser = LinkParser()
    parser.feed(html)
    parser.close()
    return [("".join(parts), href) for parts, href in parser.links]
