from html.parser import HTMLParser


def extract_links(html):
    class LinkParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.links = []
            self.open_links = []

        def handle_starttag(self, tag, attrs):
            if tag == "a":
                href = next((value for name, value in attrs if name == "href"), None)
                index = len(self.links)
                self.links.append(None)
                self.open_links.append((index, href, []))

        def handle_data(self, data):
            for _, _, text_parts in self.open_links:
                text_parts.append(data)

        def handle_endtag(self, tag):
            if tag == "a" and self.open_links:
                index, href, text_parts = self.open_links.pop()
                self.links[index] = ("".join(text_parts), href)

    parser = LinkParser()
    parser.feed(html)
    parser.close()

    # Include links whose closing tag is missing.
    while parser.open_links:
        parser.handle_endtag("a")

    return parser.links
