from bs4 import BeautifulSoup


def extract_first_table(html):
    soup = BeautifulSoup(html, "html.parser")
    table = soup.find("table")
    if table is None:
        raise ValueError("Page has no table")

    headers = [
        th.get_text().strip()
        for th in table.find_all("th")
        if th.find_parent("table") is table
    ]

    rows = []
    for tr in table.find_all("tr"):
        if tr.find_parent("table") is not table:
            continue
        cells = [
            td.get_text().strip()
            for td in tr.find_all("td")
            if td.find_parent("tr") is tr and td.find_parent("table") is table
        ]
        if cells:
            rows.append(cells)

    if not rows:
        raise ValueError("First table has no data rows")

    return headers, rows
```

