import math

def row_zscores_and_correlation(data):
    """Return row z-scores and their column-wise Pearson correlations."""
    if len(data) < 2 or not data[0] or any(len(row) != len(data[0]) for row in data):
        raise ValueError("data must be a rectangular matrix with at least two rows")

    zscores = []
    for row in data:
        mean = math.fsum(row) / len(row)
        deviations = [x - mean for x in row]
        sd = math.sqrt(math.fsum(d * d for d in deviations) / len(row))
        if sd == 0:
            raise ValueError("each row must have nonzero standard deviation")
        zscores.append([d / sd for d in deviations])

    columns = list(zip(*zscores))
    centered = [
        [x - math.fsum(col) / len(col) for x in col]
        for col in columns
    ]
    magnitudes = [math.sqrt(math.fsum(x * x for x in col)) for col in centered]
    if any(m == 0 for m in magnitudes):
        raise ValueError("each z-score column must have nonzero standard deviation")

    correlation = [
        [
            1.0 if i == j else
            math.fsum(a * b for a, b in zip(centered[i], centered[j]))
            / (magnitudes[i] * magnitudes[j])
            for j in range(len(columns))
        ]
        for i in range(len(columns))
    ]
    return zscores, correlation
```

