import math


def integer_histogram_counts(data_str, separator=',', bins=20):
    if not data_str.strip():
        raise ValueError("data_str must contain at least one number")
    if not isinstance(bins, int) or isinstance(bins, bool) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    values = []
    for part in data_str.split(separator):
        try:
            number = float(part.strip())
            if not math.isfinite(number):
                raise ValueError
            values.append(int(number))
        except ValueError:
            raise ValueError(f"invalid numeric value: {part!r}") from None

    counts = [0] * bins
    low, high = min(values), max(values)

    for value in values:
        # Assign the maximum to the last bin; handle identical values too.
        index = min((value - low) * bins // (high - low), bins - 1) if high != low else bins - 1
        counts[index] += 1

    return values, counts
```

