def standardize_filtered(data, age, weight):
    ages = data["Age"]        # Raises KeyError if missing
    weights = data["Weight"]  # Raises KeyError if missing

    kept = [
        i for i, (a, w) in enumerate(zip(ages, weights))
        if a < age and w > weight
    ]

    result = {}
    for name, column in data.items():
        values = [column[i] for i in kept]
        if not values:
            result[name] = []
            continue

        mean = sum(values) / len(values)
        variance = sum((x - mean) ** 2 for x in values) / len(values)
        result[name] = (
            [(x - mean) / variance**0.5 for x in values]
            if variance else [0.0] * len(values)
        )

    return result
