import fnmatch
import re


def extract_matches_from_files(files, name_pattern, value_pattern):
    def natural_key(name):
        return tuple(
            (1, int(part)) if part.isdigit() else (0, part)
            for part in re.split(r"(\d+)", name)
        )

    names = [name for name in files if fnmatch.fnmatchcase(name, name_pattern)]
    if not names:
        raise ValueError(f"No file names match {name_pattern!r}")

    regex = re.compile(value_pattern)
    return [
        (name, [match.group(0) for match in regex.finditer(files[name])])
        for name in sorted(names, key=lambda name: (natural_key(name), name))
    ]
