import fnmatch
import re


def extract_matches_from_files(files, name_pattern, value_pattern):
    def natural_key(filename):
        parts = re.split(r"(\d+)", filename)
        return (
            tuple((1, int(part)) if part.isdigit() else (0, part.casefold())
                  for part in parts),
            filename,
        )

    selected = [name for name in files if fnmatch.fnmatchcase(name, name_pattern)]
    if not selected:
        raise ValueError("No file names match the wildcard")

    regex = re.compile(value_pattern)
