import math

def highly_correlated_column_pairs(data, cols, threshold):
    if not 0 <= threshold <= 1:
        raise ValueError("threshold must be between 0 and 1")

    if len(data) < 2:
        return []

    centered = []
    squared_sums = []
    for column in zip(*data):
        mean = math.fsum(column) / len(data)
        values = [value - mean for value in column]
        centered.append(values)
        squared_sums.append(math.fsum(value * value for value in values))

    result = []
    for i in range(len(cols)):
        for j in range(i + 1, len(cols)):
            if squared_sums[i] == 0 or squared_sums[j] == 0:
                continue  # Pearson correlation is undefined for a constant column.

            numerator = math.fsum(
                a * b for a, b in zip(centered[i], centered[j])
            )
            correlation = numerator / math.sqrt(
                squared_sums[i] * squared_sums[j]
            )
            if abs(correlation) > threshold:
                result.append((cols[i], cols[j]))

    return result
