from bisect import bisect_right
from math import isfinite


def histogram_bins(values, bins):
    values = [float(value) for value in values]
    if not all(isfinite(value) for value in values):
        raise ValueError("values must be finite numbers")

    if isinstance(bins, int) and not isinstance(bins, bool):
        if bins < 1:
            raise ValueError("bins must be a positive integer")
        if not values:
            raise ValueError("cannot determine bin edges from empty values")

        low, high = min(values), max(values)
        if low == high:
            low -= 0.5
            high += 0.5
        edges = [low + (high - low) * i / bins for i in range(bins)]
        edges.append(high)
    else:
        edges = [float(edge) for edge in bins]
        if (
            len(edges) < 2
            or not all(isfinite(edge) for edge in edges)
            or any(left >= right for left, right in zip(edges, edges[1:]))
        ):
            raise ValueError("bin edges must be finite and strictly increasing")

    counts = [0] * (len(edges) - 1)
    for value in values:
        if edges[0] <= value <= edges[-1]:
            index = min(bisect_right(edges, value) - 1, len(counts) - 1)
            counts[index] += 1

    return counts, edges
