from collections import Counter


def grayscale_histogram(data):
    if not isinstance(data, bytes):
        raise ValueError("Expected raw image bytes")

    whitespace = b" \t\r\n\v\f"
    position = 0

    def next_token():
        nonlocal position

        while position < len(data):
            if data[position] in whitespace:
                position += 1
            elif data[position] == ord("#"):
                while position < len(data) and data[position] not in b"\r\n":
                    position += 1
            else:
                break

        start = position
        while position < len(data) and data[position] not in whitespace + b"#":
            position += 1

        return data[start:position] if position > start else None

    def read_number():
        token = next_token()
        if not token or any(byte not in b"0123456789" for byte in token):
            raise ValueError("Invalid PGM number")
        return int(token)

    variant = next_token()
    if variant not in (b"P2", b"P5"):
        raise ValueError("Unsupported PGM variant")

    width = read_number()
    height = read_number()
    max_value = read_number()
    if width <= 0 or height <= 0 or not 1 <= max_value <= 255:
        raise ValueError("Invalid PGM dimensions or maximum value")

    pixel_count = width * height

    if variant == b"P5":
        # Only the header separator is consumed: a raster pixel may itself
        # be a whitespace byte or '#'.
        if position >= len(data) or data[position] not in whitespace:
            raise ValueError("Missing PGM raster separator")
        if data[position:position + 2] == b"\r\n":
            position += 2
        else:
            position += 1

        pixels = data[position:]
        if len(pixels) != pixel_count or any(p > max_value for p in pixels):
            raise ValueError("Invalid PGM raster")
        return dict(Counter(pixels))

    histogram = Counter()
    for _ in range(pixel_count):
        pixel = read_number()
        if pixel > max_value:
            raise ValueError("Pixel exceeds PGM maximum value")
        histogram[pixel] += 1

    if next_token() is not None:
        raise ValueError("Extra PGM pixel data")

    return dict(histogram)
