def grayscale_histogram(data):
    """Return the histogram of a single 8-bit P2 or P5 PGM image."""
    if not isinstance(data, bytes):
        raise ValueError("Expected image bytes")

    whitespace = b" \t\r\n\v\f"
    pos = 0

    def skip_space_and_comments():
        nonlocal pos
        while pos < len(data):
            if data[pos] in whitespace:
                pos += 1
            elif data[pos] == ord("#"):
                end = data.find(b"\n", pos)
                pos = len(data) if end == -1 else end + 1
            else:
                break

    def token():
        nonlocal pos
        skip_space_and_comments()
        start = pos
        while pos < len(data) and data[pos] not in whitespace and data[pos] != ord("#"):
            pos += 1
        if pos == start:
            raise ValueError("Missing PGM token")
        return data[start:pos]

    def integer():
        value = token()
        if not value or any(c < ord("0") or c > ord("9") for c in value):
            raise ValueError("Invalid PGM integer")
        return int(value)

    magic = token()
    if magic not in (b"P2", b"P5"):
        raise ValueError("Not a P2 or P5 PGM image")

    width, height, maxval = integer(), integer(), integer()
    if width <= 0 or height <= 0 or not 1 <= maxval <= 255:
        raise ValueError("Invalid PGM dimensions or maximum value")

    count = width * height
    histogram = {}

    if magic == b"P5":
        # The raster begins immediately after the header's whitespace separator.
        if pos >= len(data) or data[pos] not in whitespace:
            raise ValueError("Missing P5 raster separator")
        separator = data[pos]
        pos += 1
        if separator == ord("\r") and pos < len(data) and data[pos] == ord("\n"):
            pos += 1

        pixels = data[pos:]
        if len(pixels) != count:
            raise ValueError("Incorrect P5 raster length")
        for value in pixels:
            if value > maxval:
                raise ValueError("Pixel exceeds maximum value")
            histogram[value] = histogram.get(value, 0) + 1
    else:
        for _ in range(count):
            value = integer()
            if value > maxval:
                raise ValueError("Pixel exceeds maximum value")
            histogram[value] = histogram.get(value, 0) + 1
        skip_space_and_comments()
        if pos != len(data):
            raise ValueError("Extra P2 raster data")

    return histogram
