        if len(data) - pos != count:
            raise ValueError("Incorrect number of P5 pixels")
        pixels = data[pos:]
        if any(pixel > max_value for pixel in pixels):
            raise ValueError("Pixel exceeds maximum value")
    else:
        pixels = []
        for _ in range(count):
            pixel = read_number()
            if pixel > max_value:
                raise ValueError("Pixel exceeds maximum value")
            pixels.append(pixel)
        skip_separators()
        if pos != len(data):
            raise ValueError("Extra P2 image data")

    return dict(Counter(pixels))
