        # The raster starts immediately after the header's whitespace delimiter.
        if pos == len(data) or data[pos] not in whitespace:
            raise ValueError("Missing P5 raster delimiter")
        start = pos + 1

        # Also accept CRLF as a single line ending when the length confirms it.
        if (
            data[pos:pos + 2] == b"\r\n"
            and len(data) - start != count
            and len(data) - (start + 1) == count
        ):
            start += 1

        pixels = data[start:]
        if len(pixels) != count:
            raise ValueError("Incorrect number of P5 pixels")

        for value in pixels:
            if value > maxval:
                raise ValueError("Pixel exceeds maximum value")
            histogram[value] = histogram.get(value, 0) + 1
    else:
        for _ in range(count):
            value = number()
            if value > maxval:
                raise ValueError("Pixel exceeds maximum value")
            histogram[value] = histogram.get(value, 0) + 1

        if token() is not None:
            raise ValueError("Extra P2 pixel data")

    return histogram
