from collections import Counter

_WHITESPACE = b" \t\r\n\v\f"


def grayscale_histogram(data):
    """Return the histogram of a single 8-bit P2 or P5 PGM image."""
    if not isinstance(data, bytes):
        raise ValueError("image data must be bytes")

    def next_token(pos):
        # Comments and whitespace are allowed between header tokens and,
        # for P2, between pixel values.
        while pos < len(data):
            if data[pos] in _WHITESPACE:
                pos += 1
            elif data[pos] == ord("#"):
                end = data.find(b"\n", pos)
                pos = len(data) if end == -1 else end + 1
            else:
                break

        start = pos
        while pos < len(data) and data[pos] not in _WHITESPACE + b"#":
            pos += 1
        return data[start:pos], pos

    def number(token):
        if not token or not token.isdigit():
            raise ValueError("invalid PGM number")
        return int(token)

    magic, pos = next_token(0)
    if magic not in (b"P2", b"P5"):
        raise ValueError("expected a P2 or P5 PGM image")

    width_token, pos = next_token(pos)
    height_token, pos = next_token(pos)
    maxval_token, pos = next_token(pos)
    width, height, maxval = map(
        number, (width_token, height_token, maxval_token)
    )
    if width < 1 or height < 1 or not 1 <= maxval <= 255:
        raise ValueError("invalid PGM dimensions or maximum value")

    pixel_count = width * height

    if magic == b"P5":
        # The binary raster starts immediately after the header separator.
        if pos == len(data) or data[pos] not in _WHITESPACE:
            raise ValueError("missing P5 raster separator")
        pos += 1
        if data[pos - 1:pos] == b"\r" and data[pos:pos + 1] == b"\n":
            pos += 1  # Also accept a CRLF line ending.

        pixels = data[pos:]
        if len(pixels) != pixel_count or any(p > maxval for p in pixels):
            raise ValueError("invalid P5 raster")
        return dict(Counter(pixels))

    histogram = Counter()
    for _ in range(pixel_count):
        token, pos = next_token(pos)
        value = number(token)
        if value > maxval:
            raise ValueError("pixel exceeds PGM maximum value")
        histogram[value] += 1

    extra, _ = next_token(pos)
    if extra:
        raise ValueError("extra P2 pixel data")
    return dict(histogram)
