def classical_seasonal_decomposition(values, period, model="additive"):
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if isinstance(period, bool) or not isinstance(period, int) or period < 1:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")
    if model == "multiplicative" and any(value <= 0 for value in values):
        raise ValueError("multiplicative decomposition requires positive values")

    # Compute the period-length moving averages.
    window_sum = sum(values[:period])
    moving = [window_sum / period]
    for start in range(1, n - period + 1):
        window_sum += values[start + period - 1] - values[start - 1]
        moving.append(window_sum / period)

    trend = [None] * n
    if period % 2:
        for start, average in enumerate(moving):
            trend[start + period // 2] = average
    else:
        for start in range(len(moving) - 1):
            trend[start + period // 2] = (moving[start] + moving[start + 1]) / 2

    phase_values = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            detrended = (
                value - trend[i]
                if model == "additive"
                else value / trend[i]
            )
            phase_values[i % period].append(detrended)

    phase_means = [sum(group) / len(group) for group in phase_values]
    if model == "additive":
        offset = sum(phase_means) / period
        factors = [mean - offset for mean in phase_means]
    else:
        scale = sum(phase_means) / period
        factors = [mean / scale for mean in phase_means]

    seasonal = [factors[i % period] for i in range(n)]
    resid = [
        None if trend[i] is None else (
            values[i] - trend[i] - seasonal[i]
            if model == "additive"
            else values[i] / (trend[i] * seasonal[i])
        )
        for i in range(n)
    ]
    return {"trend": trend, "seasonal": seasonal, "resid": resid}
