                groups[i % period].append(value / trend[i])

    pattern = [sum(group) / len(group) for group in groups]
    mean = sum(pattern) / period
    if model == 'additive':
        pattern = [component - mean for component in pattern]
    else:
        if mean == 0:
            raise ValueError("multiplicative seasonal factors cannot be normalized")
        pattern = [component / mean for component in pattern]

