    overall_mean = sum(phase_means) / period

    if model == 'additive':
        factors = [mean - overall_mean for mean in phase_means]
    else:
        if overall_mean == 0:
            raise ValueError("multiplicative seasonal factors cannot be normalized")
        factors = [mean / overall_mean for mean in phase_means]
        if 0 in factors:
            raise ValueError("multiplicative seasonal factors must be nonzero")

