    half = period // 2
    if period % 2:
        for t in range(half, n - half):
            trend[t] = moving[t - half]
    else:
        for t in range(half, n - half):
            trend[t] = (moving[t - half] + moving[t - half + 1]) / 2

    detrended = [
        (values[t] - trend[t] if model == "additive"
         else values[t] / trend[t])
        for t in range(n) if trend[t] is not None
    ]
    phases = [
        t % period for t in range(n) if trend[t] is not None
    ]
    phase_means = [
        sum(x for x, phase in zip(detrended, phases) if phase == p)
        / phases.count(p)
        for p in range(period)
    ]

    mean = sum(phase_means) / period
    if model == "additive":
        phase_means = [x - mean for x in phase_means]
    else:
        phase_means = [x / mean for x in phase_means]

    seasonal = [phase_means[t % period] for t in range(n)]
    resid = [
        None if trend[t] is None else (
            values[t] - trend[t] - seasonal[t]
            if model == "additive"
            else values[t] / (trend[t] * seasonal[t])
        )
        for t in range(n)
    ]

    return {"trend": trend, "seasonal": seasonal, "resid": resid}
