import csv
import io
import math
import re
import statistics

_NUMBER = re.compile(
    r"[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)"
    r"(?:[eE][+-]?\d+)?"
)


def summarize_numeric_csv(csv_text):
    """Summarize columns whose data cells are all finite numbers."""
    reader = csv.reader(io.StringIO(csv_text))
    headers = next(reader, [])
    rows = list(reader)

    if any(len(row) != len(headers) for row in rows):
        raise ValueError("CSV rows must have the same number of fields as the header")

    groups = {}
    for index, name in enumerate(headers):
        values = []
        for row in rows:
            text = row[index].strip()
            if not _NUMBER.fullmatch(text):
                break
            value = float(text.replace(",", ""))
            if not math.isfinite(value):
                break
            values.append(value)
        else:
            if values:
                groups[name] = values

    means = {name: statistics.fmean(values) for name, values in groups.items()}
    std_devs = {
        name: statistics.stdev(values) if len(values) >= 2 else None
        for name, values in groups.items()
    }

    f_value = None
    if len(groups) >= 2:
        n = sum(map(len, groups.values()))
        within_df = n - len(groups)
        if within_df > 0:
            grand_mean = statistics.fmean(
                value for values in groups.values() for value in values
            )
            between = sum(
                len(values) * (means[name] - grand_mean) ** 2
                for name, values in groups.items()
            )
            within = sum(
                (value - means[name]) ** 2
                for name, values in groups.items()
                for value in values
            )
            f_value = (
                (between / (len(groups) - 1)) / (within / within_df)
                if within
                else (math.inf if between else None)
            )

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
```

