import csv
import math
import re
import statistics
from io import StringIO

_THOUSANDS_NUMBER = re.compile(
    r"[+-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?(?:[eE][+-]?\d+)?"
)


def summarize_numeric_csv(csv_text):
    reader = csv.reader(StringIO(csv_text))
    headers = next(reader, None)
    if headers is None:
        raise ValueError("CSV must have a header row")
    if len(headers) != len(set(headers)):
        raise ValueError("Column names must be unique")

    rows = list(reader)
    if any(len(row) != len(headers) for row in rows):
        raise ValueError("Every row must have the same number of fields as the header")

    def parse_number(text):
        text = text.strip()
        if "," in text:
            if not _THOUSANDS_NUMBER.fullmatch(text):
                raise ValueError("Invalid thousands separator")
            text = text.replace(",", "")
        value = float(text)
        if not math.isfinite(value):
            raise ValueError("Not a finite number")
        return value

    columns = {}
    for index, name in enumerate(headers):
        try:
            columns[name] = [parse_number(row[index]) for row in rows]
        except ValueError:
            pass  # Ignore a column if any of its values is not a number.

    if columns and len(rows) < 2:
        raise ValueError("At least two data rows are needed for sample standard deviations")

    means = {name: statistics.fmean(values) for name, values in columns.items()}
    std_devs = {name: statistics.stdev(values) for name, values in columns.items()}

    f_value = None
    if len(columns) >= 2:
        n = len(rows)
        k = len(columns)
        grand_mean = statistics.fmean(means.values())
        between = n * sum((mean - grand_mean) ** 2 for mean in means.values())
        within = sum(
            sum((value - means[name]) ** 2 for value in values)
            for name, values in columns.items()
        )
        mean_square_between = between / (k - 1)
        mean_square_within = within / (k * (n - 1))
        f_value = (
            mean_square_between / mean_square_within
            if mean_square_within
            else math.inf if mean_square_between else math.nan
        )

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
```

When every numeric group is constant, the within-group variance is zero: the function returns `inf` for a positive between-group variance and `nan` if that variance is also zero.

