import csv
import math
import re
import statistics

_PLAIN_NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?\Z")
_GROUPED_NUMBER = re.compile(
    r"[+-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?(?:[eE][+-]?\d+)?\Z"
)


def summarize_numeric_csv(csv_text):
    rows = list(csv.reader(csv_text.splitlines()))
    if not rows:
        raise ValueError("CSV must have a header row")

    headers, *data = rows
    if any(len(row) != len(headers) for row in data):
        raise ValueError("Every row must have the same number of fields as the header")

    groups = {}
    for name, fields in zip(headers, zip(*data)):
        values = []
        for field in fields:
            text = field.strip()
            if not (_PLAIN_NUMBER.fullmatch(text) or _GROUPED_NUMBER.fullmatch(text)):
                break
            value = float(text.replace(",", ""))
            if not math.isfinite(value):
                break
            values.append(value)
        else:
            if values:
                groups[name] = values

    if any(len(values) < 2 for values in groups.values()):
        raise ValueError("Sample standard deviation requires at least two rows")

    means = {name: statistics.mean(values) for name, values in groups.items()}
    std_devs = {name: statistics.stdev(values) for name, values in groups.items()}

    f_value = None
    if len(groups) >= 2:
        all_values = [value for values in groups.values() for value in values]
        grand_mean = statistics.mean(all_values)
        between = math.fsum(
            len(values) * (means[name] - grand_mean) ** 2
            for name, values in groups.items()
        )
        within = math.fsum(
            (value - means[name]) ** 2
            for name, values in groups.items()
            for value in values
        )
        if within == 0:
            f_value = math.inf if between > 0 else math.nan
        else:
            f_value = (between / (len(groups) - 1)) / (
                within / (len(all_values) - len(groups))
            )

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
```

