import math
from numbers import Real


def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    standardized = {}
    numeric_columns = []

    for name, values in table.items():
        if values and all(isinstance(v, Real) and not isinstance(v, bool)
                          for v in values):
            mean = math.fsum(values) / len(values)
            variance = math.fsum((v - mean) ** 2 for v in values) / len(values)
            if variance == 0:
                raise ValueError(f"numeric column {name!r} is constant")

            scale = math.sqrt(variance)
            scaled = [(v - mean) / scale for v in values]
            standardized[name] = scaled
            numeric_columns.append(scaled)
        else:
            standardized[name] = values.copy()

    if not numeric_columns:
        raise ValueError("table has no numeric columns")

    n = len(numeric_columns[0])
    corr = [
        [math.fsum(a * b for a, b in zip(left, right)) / n
         for right in numeric_columns]
        for left in numeric_columns
    ]
    return standardized, corr
