import math
from numbers import Real


def standardize_and_correlate(table):
    if not table:
        raise ValueError("Table is empty")

    standardized = {}
    numeric = {}

    for name, values in table.items():
        if values and all(isinstance(v, Real) and not isinstance(v, bool)
                          for v in values):
            mean = math.fsum(values) / len(values)
            centered = [v - mean for v in values]
            sum_squares = math.fsum(v * v for v in centered)

            if sum_squares == 0:
                raise ValueError(f"Numeric column {name!r} has zero standard deviation")

            std = math.sqrt(sum_squares / len(values))
            standardized[name] = [v / std for v in centered]
            numeric[name] = (centered, sum_squares)
        else:
            standardized[name] = list(values)

    if not numeric:
        raise ValueError("Table has no numeric columns")

    columns = list(numeric)
    corr = []
    for i, left in enumerate(columns):
        row = []
        for j, right in enumerate(columns):
            if i == j:
                row.append(1.0)
            else:
                x, x_squares = numeric[left]
                y, y_squares = numeric[right]
                covariance_sum = math.fsum(a * b for a, b in zip(x, y))
                row.append(covariance_sum / math.sqrt(x_squares * y_squares))
        corr.append(row)

    return standardized, corr
