from numbers import Real


def standardize_and_correlate(table):
    if not table:
        raise ValueError("Table is empty")

    lengths = {len(column) for column in table.values()}
    if len(lengths) != 1:
        raise ValueError("Columns must have equal lengths")

    n = lengths.pop()
    standardized = {}
    numeric_columns = []

    for name, values in table.items():
        is_numeric = all(
            isinstance(value, Real) and not isinstance(value, bool)
            for value in values
        )
        if not is_numeric:
            standardized[name] = list(values)
            continue

        if n == 0:
            raise ValueError("Cannot standardize an empty numeric column")

        mean = fsum(values) / n
        std = sqrt(fsum((value - mean) ** 2 for value in values) / n)
        if std == 0:
            raise ValueError(f"Numeric column {name!r} has zero variance")

        scaled = [(value - mean) / std for value in values]
        standardized[name] = scaled
        numeric_columns.append(scaled)

    if not numeric_columns:
        raise ValueError("Table has no numeric columns")

    corr = [
        [
            1.0 if i == j else fsum(a * b for a, b in zip(x, y)) / n
            for j, y in enumerate(numeric_columns)
        ]
        for i, x in enumerate(numeric_columns)
    ]
    return standardized, corr
