            standardized[name] = [v / std for v in centered]
            numeric.append((centered, sum_squares))
        else:
            standardized[name] = list(values)

    if not numeric:
        raise ValueError("The table has no numeric columns.")

    corr = [
        [
            1.0 if i == j else
            math.fsum(a * b for a, b in zip(x, y)) / math.sqrt(sx * sy)
            for j, (y, sy) in enumerate(numeric)
        ]
        for i, (x, sx) in enumerate(numeric)
    ]
    return standardized, corr
