import math

def feature_correlation_matrix(samples):
    """Return Pearson correlations between columns of samples."""
    if not samples:
        return []

    feature_count = len(samples[0])
    columns = list(zip(*samples))
    means = [math.fsum(column) / len(samples) for column in columns]
    centered = [
        [value - mean for value in column]
        for column, mean in zip(columns, means)
    ]
    sums_of_squares = [
        math.fsum(value * value for value in column)
        for column in centered
    ]

    matrix = [[float("nan")] * feature_count for _ in range(feature_count)]
    for i in range(feature_count):
        if sums_of_squares[i] == 0:
            continue  # Pearson correlation is undefined for a constant feature.

        matrix[i][i] = 1.0
        for j in range(i + 1, feature_count):
            if sums_of_squares[j] == 0:
                continue
            numerator = math.fsum(
                a * b for a, b in zip(centered[i], centered[j])
            )
            correlation = numerator / math.sqrt(
                sums_of_squares[i] * sums_of_squares[j]
            )
            matrix[i][j] = matrix[j][i] = correlation

    return matrix
```

Correlations involving a constant feature are returned as `nan` because Pearson correlation is undefined for them.

