from html.parser import HTMLParser


def extract_table_rows(html):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.open_rows = []
            self.open_cells = []  # (text fragments, row depth)

        def handle_starttag(self, tag, attrs):
            if tag == "tr":
                row = []
                self.rows.append(row)
                self.open_rows.append(row)
            elif tag == "td" and self.open_rows:
                depth = len(self.open_rows)
                # A new cell implicitly ends the previous cell in this row.
                if self.open_cells and self.open_cells[-1][1] == depth:
                    self.open_cells.pop()

                fragments = []
                for row in self.open_rows:
                    row.append(fragments)
                self.open_cells.append((fragments, depth))

        def handle_endtag(self, tag):
            if tag == "td" and self.open_cells:
                self.open_cells.pop()
            elif tag == "tr" and self.open_rows:
                depth = len(self.open_rows)
                self.open_cells = [
                    cell for cell in self.open_cells if cell[1] < depth
                ]
                self.open_rows.pop()

        def handle_data(self, data):
            for fragments, _ in self.open_cells:
                fragments.append(data)

    parser = TableParser()
    parser.feed(html)
    parser.close()
    return [
        ["".join(fragments).strip() for fragments in row]
        for row in parser.rows
    ]
